INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$189d6ee5-fb1b-51a8-bb81-368975fc6498$ml$::uuid, $ml$cleanenergy$ml$, 1, 1, $ml${"id": "cleanenergy-d1-c1", "title": "A grid operator crosses the divide", "lessonTitle": "How the grid actually works", "slot": 1, "type": "apply", "brief": {"headline": "On April 1, 2026, the Southwest Power Pool began running grid services for seven western utilities and agencies. It became the first regional operator to span both the Eastern and Western grids.", "kicker": "Apply the map: which layer did SPP just take over?", "fullText": "SPP already ran the high-voltage grid and market across the central US. In April 2026 it added Basin Electric, Colorado Springs Utilities, Deseret Power, the Municipal Energy Agency of Nebraska, Platte River Power Authority, Tri-State and three regions of the Western Area Power Administration.\n\nSPP owns no power plants and no wires. It is a not-for-profit operator: it watches the grid around the clock, plans transmission and runs the market that decides which plants run. Retail rates and local decisions stay with states and the utilities themselves.", "sources": [{"url": "https://www.tdworld.com/utility-business/news/55368312/spp-and-western-utilities-confirm-support-for-rtos-april-1-expansion", "label": "T&D World, SPP expands into the West, April 2026"}, {"url": "https://www.ferc.gov/industries-data/market-assessments/electric-power-markets", "label": "FERC, electric power markets"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did the western utilities hand to SPP?", "options": ["Running the high-voltage grid and its market", "Ownership of their power plants", "Setting the retail rates their customers pay"], "correctIndex": 0, "explanation": "SPP owns neither plants nor wires. Like other ISOs and RTOs, it operates the high-voltage grid and runs the market, while retail rates stay local."}, "numbers": {"kind": "numberSense", "prompt": "How many western utilities and agencies joined SPP on April 1, 2026, counting WAPA once?", "min": 0, "max": 20, "value": 7, "explanation": "Seven, with the Western Area Power Administration counted once even though three of its regions joined."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at Tri-State in Colorado. They ask what changed for their grid in April 2026.", "prompt": "Which answer shows you know the map?", "options": ["SPP bought its plants and transmission lines", "Nothing, since it is still in the Western grid", "SPP now runs the grid and market it trades in"], "correctIndex": 2, "consequences": ["SPP owns no plants or wires; it operates the system.", "It stays in the Western grid, but its operator changed.", "You name the operator and its role, which is what they want."], "explanation": "Tri-State kept its assets. What moved was the operator role: SPP now runs the high-voltage grid and market around it."}, "proReasoning": "Strong candidates name the operator and its job in one line: SPP runs the grid and market, Tri-State owns plants and lines. It shows you know who decides what runs.", "commonMistake": "Confusing the operator with an owner. ISOs and RTOs run the system; they do not buy the assets.", "mentalModel": "Name the operator, then say what it runs."}, "invest": {"call": {"kind": "theCall", "situation": "You hold a stake in a wind farm in Colorado. Its region just joined SPP.", "prompt": "What changes most for the farm?", "options": ["The market rules that set what it earns", "Its owners, who now answer to SPP", "Its wind speeds and turbine output"], "correctIndex": 0, "consequences": ["A new operator means new market rules and prices.", "Ownership stays the same; SPP owns nothing.", "Weather and hardware do not change with the operator."], "explanation": "Each operator runs its own market. Joining SPP changes how the farm is dispatched and paid, not who owns it."}, "proReasoning": "Investors read an operator change as a market change. The same plant can earn differently under new dispatch and pricing rules.", "commonMistake": "Assuming a grid operator change is just paperwork. It decides when your plant runs.", "mentalModel": "New operator, new market, new revenue math."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell software that helps plants bid into grid markets. Seven western utilities just joined SPP.", "prompt": "Who is your best first lead?", "options": ["Homeowners served by those utilities", "Plant owners now bidding into a new market", "SPP itself, which owns their plants"], "correctIndex": 1, "consequences": ["Homeowners never bid into the wholesale market.", "They must learn new market rules fast, which is your product.", "SPP owns no plants, so it does not bid them."], "explanation": "The change creates a learning curve for generators entering the SPP market. Bidding tools sell to whoever has to bid."}, "proReasoning": "Founders spot the moment a buyer faces new rules. A market expansion is a window when plant owners need help most.", "commonMistake": "Pitching the operator for a generator problem. Each layer has its own buyer.", "mentalModel": "A rule change is a sales window."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why one grid operator spanning two grids is a first.", "prompt": "What's the best short answer?", "options": ["Grid operators usually own the power plants", "Most of the US has no grid operator at all", "The US grid is split into separate big grids"], "correctIndex": 2, "consequences": ["Operators run the system; plants belong to others.", "Two-thirds of US load is in operator regions.", "Eastern, Western and Texas grids run mostly apart, so this is new."], "explanation": "The US has three big grids. Until 2026, no regional operator ran parts of both the Eastern and Western ones."}, "proReasoning": "Picture three big grids joined only by a few links. Then a single operator on both sides looks like the milestone it is.", "commonMistake": "Thinking the US has one connected grid run from one place.", "mentalModel": "Three grids, many operators, one first."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3aa206579297$ml$]::text[]),
($ml$f60b6742-cfc5-5982-b155-62ea202270f4$ml$::uuid, $ml$cleanenergy$ml$, 1, 2, $ml${"id": "cleanenergy-d1-c2", "title": "Who does what on the grid", "lessonTitle": "How the grid actually works", "slot": 2, "type": "connect", "brief": {"headline": "Power plants generate, high-voltage lines move power far, and local lines bring it home. In two-thirds of the US, an independent operator also runs the high-voltage grid and decides which plants run.", "kicker": "Connect the layers to the operator that runs them.", "fullText": "EIA describes electricity as a chain: generation at power plants, transmission over high-voltage lines, and distribution over local lines to homes and businesses. Supply must match demand every moment along that chain.\n\nFERC counts seven regional operators, from CAISO in California to PJM in the Mid-Atlantic and ERCOT in Texas. Two-thirds of US electricity load is served in their regions. They run the grid independently of the companies selling power, and their markets choose which plants run.", "sources": [{"url": "https://www.eia.gov/energyexplained/electricity/delivery-to-consumers.php", "label": "EIA, delivery to consumers"}, {"url": "https://www.ferc.gov/industries-data/market-assessments/electric-power-markets", "label": "FERC, electric power markets"}]}, "evidence": {"kind": "sortSignal", "prompt": "Who does each job in an ISO region?", "buckets": ["Power plant", "Grid operator", "Local utility"], "items": [{"text": "Generates the electricity", "bucket": 0}, {"text": "Bids into the market to be chosen", "bucket": 0}, {"text": "Decides which plants run each hour", "bucket": 1}, {"text": "Keeps supply and demand balanced", "bucket": 1}, {"text": "Runs the local lines to your street", "bucket": 2}, {"text": "Sends the bill to your home", "bucket": 2}], "explanation": "Plants generate and bid. The ISO dispatches and balances the high-voltage system. The local utility handles distribution and customers."}, "numbers": {"kind": "numberSense", "prompt": "What share of US electricity load is served in regions with an independent grid operator?", "min": 0, "max": 100, "value": 67, "unit": "%", "explanation": "About two-thirds. Most Americans get power through a grid run by an ISO or RTO."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You have offers from PJM and from a local utility in its region.", "prompt": "Which job puts you closest to deciding which plants run?", "options": ["PJM, which dispatches plants through its market", "The utility, which sends you the monthly bills", "Neither, since each plant decides when it runs"], "correctIndex": 0, "consequences": ["PJM picks plants from its market every hour.", "The utility runs local lines and serves customers.", "Plants bid; the operator decides."], "explanation": "In an ISO region, the operator dispatches. The utility handles distribution and billing."}, "proReasoning": "Candidates who sort roles by layer pick jobs with their eyes open. Dispatch lives at the operator; customers live at the utility.", "commonMistake": "Assuming the company on your bill runs the whole system.", "mentalModel": "Match the job to the layer."}, "invest": {"call": {"kind": "theCall", "situation": "You compare a power plant owner and a local wires utility in the same ISO region.", "prompt": "Whose sales depend most on winning in the market?", "options": ["Both equally, since they share one grid", "The plant owner, which must be dispatched", "The wires utility, which owns local lines"], "correctIndex": 1, "consequences": ["They sit in different layers with different revenue.", "A plant earns only when the operator picks it.", "Wires utilities earn on their lines, not on dispatch."], "explanation": "Generators compete in the operator's market. Distribution utilities are paid for running local lines."}, "proReasoning": "Investors separate market risk from wires revenue. The layer tells you whether earnings depend on being chosen.", "commonMistake": "Treating every power company as the same kind of business.", "mentalModel": "Generators compete; wires collect."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your tool predicts outages on local lines a day ahead.", "prompt": "Who do you sell to first?", "options": ["Grid operators like PJM and CAISO in their regions", "Power plants bidding into wholesale markets", "Local utilities that run distribution lines"], "correctIndex": 2, "consequences": ["Operators run the high-voltage grid, not street lines.", "Plants do not fix local outages.", "They own and repair the lines your tool watches."], "explanation": "Distribution belongs to local utilities. A tool for local lines sells to whoever runs them."}, "proReasoning": "Founders map their product to one layer before pitching. Local line problems belong to the local utility.", "commonMistake": "Pitching the biggest name on the grid instead of the owner of the problem.", "mentalModel": "Each layer has its own buyer."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your lights flicker during a heat wave. A friend blames the power plant down the road.", "prompt": "What's the more accurate picture?", "options": ["Many plants and lines feed you, balanced live", "Your home runs on that one nearby plant alone", "Your utility makes all of your power by itself"], "correctIndex": 0, "consequences": ["An operator balances many sources over a shared grid.", "Power from many plants mixes on the grid.", "In ISO regions, many owners supply the market."], "explanation": "Electricity flows over a shared grid from many plants, and an operator keeps supply matching demand every second."}, "proReasoning": "Think of the grid as a pool, not a pipe. Many plants pour in, and someone keeps the level steady.", "commonMistake": "Picturing a private line from one plant to your home.", "mentalModel": "The grid is a pool balanced every second."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:924bfdfac08f$ml$]::text[]),
($ml$9fc56f9f-693a-5a0b-8a84-7ed0cd0274da$ml$::uuid, $ml$cleanenergy$ml$, 1, 3, $ml${"id": "cleanenergy-d1-c3", "title": "Picking a region for a data center", "lessonTitle": "How the grid actually works", "slot": 3, "type": "decide", "brief": {"headline": "You plan a data center and must pick a state. FERC lists seven regional grid operators, each with its own market rules, and Texas runs mostly on its own grid under ERCOT.", "kicker": "Decide: what do you learn about a region before choosing it?", "fullText": "You run site selection for a company building a data center. Power is your biggest operating cost, so the grid behind each site matters.\n\nFERC counts seven regional operators: CAISO, MISO, ISO New England, NYISO, PJM, SPP and ERCOT. Each runs its own market and has its own challenges. Most of Texas sits on a separate grid run by ERCOT, apart from the Eastern and Western grids. Electricity is made the instant it is used, so someone runs each grid every second.", "sources": [{"url": "https://www.ferc.gov/industries-data/market-assessments/electric-power-markets", "label": "FERC, electric power markets"}, {"url": "https://www.eia.gov/energyexplained/electricity/delivery-to-consumers.php", "label": "EIA, delivery to consumers"}]}, "evidence": {"kind": "faceOff", "prompt": "For a site in Dallas, who decides which power plants run each hour?", "left": {"name": "ERCOT", "note": "Runs most of the Texas grid"}, "right": {"name": "The local utility", "note": "Runs the lines to the site"}, "correctIndex": 0, "explanation": "ERCOT operates the Texas grid and its market. Local utilities run distribution but do not dispatch plants."}, "numbers": {"kind": "numberSense", "prompt": "How many regional grid operators does FERC count in the US?", "min": 0, "max": 20, "value": 7, "explanation": "Seven: CAISO, MISO, ISO New England, NYISO, PJM, SPP and ERCOT."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks what to check first about a site in Ohio.", "prompt": "What do you answer?", "options": ["Whether the state gets plenty of sunny weather", "Which operator runs the grid and its rules", "How many homes sit on the same street as the site"], "correctIndex": 1, "consequences": ["Weather matters less than market rules here.", "The operator's market sets prices and access.", "Homes nearby tell you little about grid rules."], "explanation": "Each operator has its own market rules and challenges. Naming it is the first step."}, "proReasoning": "A strong analyst opens with the operator: PJM for most of Ohio. Prices and access rules follow from that.", "commonMistake": "Starting with land and taxes before knowing whose grid you join.", "mentalModel": "Name the operator before the site."}, "invest": {"call": {"kind": "theCall", "situation": "You are valuing two identical data centers, one in Texas and one in Virginia.", "prompt": "Why might their power costs differ?", "options": ["Data centers always pay one national price", "Only the building design sets power costs", "They sit in different grids and markets"], "correctIndex": 2, "consequences": ["There is no single national power price.", "Location shapes the price as much as design.", "ERCOT and PJM run separate markets with different prices."], "explanation": "Each operator runs its own market, so where a facility sits shapes what it pays."}, "proReasoning": "Investors treat the grid region as a cost driver. The same load pays different prices in different markets.", "commonMistake": "Assuming power costs the same everywhere in the US.", "mentalModel": "Location shapes the power bill."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to sell grid analysis to data center builders. You have time for one region first.", "prompt": "How do you choose?", "options": ["Pick one operator and learn its rules deeply", "Cover all regions with one generic report", "Skip grid rules and sell on price alone"], "correctIndex": 0, "consequences": ["Depth in one market beats shallow coverage.", "Each operator differs, so generic advice misses.", "Rules are what buyers need help with."], "explanation": "Every operator has different rules. Mastering one first gives buyers real answers."}, "proReasoning": "Founders win by knowing one market better than anyone. Seven operators means seven rulebooks.", "commonMistake": "Treating the US grid as one market from day one.", "mentalModel": "One operator, mastered first."}, "curiosity": {"call": {"kind": "theCall", "situation": "You hear Texas could not borrow much power from other states in a storm.", "prompt": "Why would that be?", "options": ["Other states refuse to sell their power to Texas", "Most of Texas runs on its own separate grid", "Texas has hardly any power plants of its own"], "correctIndex": 1, "consequences": ["The limit is physical links, not refusal.", "ERCOT sits apart from the Eastern and Western grids.", "Texas has plenty of plants of its own."], "explanation": "Most of Texas is on ERCOT's grid, separate from the other two big US grids."}, "proReasoning": "Knowing the three grids explains a lot of news. Texas mostly stands alone.", "commonMistake": "Assuming every state can pull power from every other.", "mentalModel": "Texas is its own grid."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:340bb44dce5b$ml$]::text[]),
($ml$099b4f74-39c6-5ac2-a449-6ea4bd2c8aad$ml$::uuid, $ml$cleanenergy$ml$, 2, 1, $ml${"id": "cleanenergy-d2-c1", "title": "The $9,000 hours", "lessonTitle": "How electricity gets priced", "slot": 1, "type": "apply", "brief": {"headline": "During the February 2021 freeze, Texas power prices sat at the $9,000 per MWh cap. The market monitor later said ERCOT held them too high for nearly two days after outages ended, costing an estimated $16 billion.", "kicker": "Apply the pricing rule to the Texas freeze.", "fullText": "Widespread outages in Texas ended late on February 17, 2021. Prices stayed at the $9,000 per megawatt-hour maximum for nearly two more days. Potomac Economics, the independent market monitor, estimated the error cost power companies about $16 billion.\n\nOn March 5, the Public Utility Commission declined to reprice those hours, saying a reversal could hurt many consumers. Later that year it cut the cap from $9,000 to $5,000 per megawatt-hour.", "sources": [{"url": "https://abc13.com/post/puc-texas-meeting-public-utility-commission-ercot/10390632/", "label": "ABC13, Texas PUC rejects $16 billion ERCOT charge correction"}, {"url": "https://www.yahoo.com/now/texas-cuts-9-000-power-164827894.html", "label": "Yahoo News, Texas cuts $9,000 power price cap"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Prices sat at the $9,000 per MWh cap.", "The regulator repriced the hours in March 2021.", "The cap was later cut to $5,000 per MWh."], "fakeIndex": 1, "explanation": "On March 5, 2021, the commission declined to reprice. It later lowered the cap instead."}, "numbers": {"kind": "numberSense", "prompt": "How many billion dollars did the market monitor say the pricing error cost?", "min": 0, "max": 50, "value": 16, "unit": "B", "explanation": "About $16 billion, from nearly two extra days at the cap."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview for a market monitoring role. They ask what a market monitor did in the Texas freeze.", "prompt": "Which answer fits?", "options": ["It flagged prices held too high after outages", "It ordered the rolling blackouts in Texas", "It set the retail bills for Texas homes"], "correctIndex": 0, "consequences": ["Potomac Economics estimated a $16 billion error.", "ERCOT ordered the blackouts, not the monitor.", "Retail bills are set elsewhere."], "explanation": "Market monitors check whether prices reflect real conditions. Here it found prices stayed at the cap too long."}, "proReasoning": "Candidates who know the monitor's role stand out. It watches prices and flags when they stop matching the grid.", "commonMistake": "Mixing up the operator, the regulator and the monitor.", "mentalModel": "Operator runs, regulator rules, monitor checks."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a Texas power retailer that bought power during the freeze.", "prompt": "What did the decision not to reprice mean for it?", "options": ["It earned the extra billions as profit", "It kept paying for hours priced at the cap", "It got refunds for every overpriced hour"], "correctIndex": 1, "consequences": ["Buyers paid; some sellers gained.", "No repricing meant buyers paid the cap prices.", "The commission declined to issue refunds."], "explanation": "Without repricing, companies that bought power in those hours were stuck with $9,000 prices."}, "proReasoning": "Investors ask who bought and who sold at the cap. The same price spike is a windfall for one and a loss for another.", "commonMistake": "Treating a price spike as good or bad for every power company alike.", "mentalModel": "Every price spike has a buyer and a seller."}, "build_startup": {"call": {"kind": "theCall", "situation": "You design a product for businesses exposed to wholesale power prices.", "prompt": "What lesson from Texas do you build in?", "options": ["Assume prices never reach the cap for long", "Ignore wholesale prices and sell on brand alone", "Protect buyers from long stretches at the cap"], "correctIndex": 2, "consequences": ["Prices sat at $9,000 for days in 2021.", "Wholesale buyers live with these prices.", "Hedging tail risk is what buyers needed in 2021."], "explanation": "The freeze showed prices can stay at the cap for days. Protection against that is the real need."}, "proReasoning": "Founders design for the bad week, not the average one. A few hours at the cap can outweigh a year of savings.", "commonMistake": "Building a product around average prices only.", "mentalModel": "Design for the tail, not the average."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why power could cost $9,000 per megawatt-hour.", "prompt": "What's the best explanation?", "options": ["Scarcity let the last unit set a capped price", "Plants always charge $9,000 in winter months", "The cap is the normal everyday price of power"], "correctIndex": 0, "consequences": ["The next unit of power set the price, up to the cap.", "Normal prices are far lower.", "The cap is a ceiling for emergencies."], "explanation": "On the grid, the next unit of power sets the price. With supply short, it rose to the cap."}, "proReasoning": "Remember the rule: the last unit needed sets the price. In a shortage, that unit is very expensive.", "commonMistake": "Thinking power prices are fixed like a menu.", "mentalModel": "The scarce last unit sets the price."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2dd8b2b6bd16$ml$]::text[]),
($ml$79289fdb-b4a5-58ce-8a48-e914f495030a$ml$::uuid, $ml$cleanenergy$ml$, 2, 2, $ml${"id": "cleanenergy-d2-c2", "title": "From the operator to the price", "lessonTitle": "How electricity gets priced", "slot": 2, "type": "connect", "brief": {"headline": "Grid operators pick plants from cheapest to costliest until demand is met. The last plant needed sets the price at each point, and in PJM a separate capacity auction cleared at its cap of $333.44 per MW-day.", "kicker": "Connect day 1 and day 2: operators run markets that set prices.", "fullText": "On day 1 you met the operators that run the grid. On day 2 you saw how they price power. They take offers and run plants in order of cost until supply meets demand. The price at each point is its locational marginal price.\n\nEnergy markets pay for power produced. PJM also runs a capacity market that pays plants to be available. Its 2027/28 auction cleared at the cap of $333.44 per MW-day. In 2025, the average US retail price was about 13.6 cents per kWh.", "sources": [{"url": "https://www.ferc.gov/industries-data/market-assessments/electric-power-markets", "label": "FERC, electric power markets"}, {"url": "https://ferc.gov/energy-markets-0", "label": "FERC, what are wholesale electricity markets"}, {"url": "https://www.utilitydive.com/news/pjm-interconnection-capacity-auction-data-center/808264/", "label": "Utility Dive, PJM 2027/28 capacity auction"}, {"url": "https://www.eia.gov/energyexplained/electricity/prices-and-factors-affecting-prices.php", "label": "EIA, prices and factors affecting prices"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the steps of setting an energy price in order.", "steps": ["Plants send offers to the grid operator", "The operator ranks offers from cheapest up", "It runs plants until supply meets demand", "The last plant needed sets the price"], "explanation": "The operator stacks offers by cost. The marginal unit, the last one needed, sets the price everyone is paid."}, "numbers": {"kind": "numberSense", "prompt": "About how many cents per kWh was the 2025 average US retail electricity price?", "min": 0, "max": 40, "value": 14, "unit": "¢", "explanation": "About 13.6 cents per kWh, covering generation, transmission and distribution."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a trading interview, you are asked why power is pricier at one PJM node than another.", "prompt": "Which answer fits?", "options": ["The node with more homes pays more", "Prices are set location by location", "PJM charges one flat price everywhere"], "correctIndex": 1, "consequences": ["Location and grid limits drive it, not home counts.", "Locational marginal prices vary across the grid.", "PJM prices differ by location."], "explanation": "Each point on the grid has its own locational marginal price."}, "proReasoning": "Traders think in nodes. Saying \"LMPs differ by location\" signals you know how the market works.", "commonMistake": "Talking about one price for a whole region.", "mentalModel": "Price lives at the node."}, "invest": {"call": {"kind": "theCall", "situation": "You compare two PJM plants that each produce the same energy.", "prompt": "What could make one earn more?", "options": ["Only how cheap its fuel is", "Nothing, since PJM pays everyone equally", "Its location price and its capacity payments"], "correctIndex": 2, "consequences": ["Fuel matters, but location and capacity do too.", "Payments vary by node and capacity.", "LMP and capacity revenue both vary."], "explanation": "PJM plants earn energy revenue at their node and capacity revenue for being ready."}, "proReasoning": "Investors add up both streams: energy at the node, capacity for readiness. The cap price of $333.44 per MW-day was a big second income.", "commonMistake": "Valuing a plant on energy sales alone.", "mentalModel": "Energy plus capacity, at the right node."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build software that helps a plant decide what to offer into the market.", "prompt": "What should it model first?", "options": ["Whether its offer will be the marginal unit", "The retail price that households pay each month", "How many power plants exist across the nation"], "correctIndex": 0, "consequences": ["Being marginal decides the price it receives.", "Retail price is set further down the chain.", "National counts do not set a local price."], "explanation": "The marginal unit sets the price. Knowing where an offer lands in the stack is the core of bidding."}, "proReasoning": "Good bidding tools focus on the stack. Where an offer lands decides whether the plant runs and what it earns.", "commonMistake": "Modeling retail prices for a wholesale decision.", "mentalModel": "Model the stack, not the bill."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a cheap wind farm gets the same price as a pricier gas plant in that hour.", "prompt": "Why does that happen?", "options": ["Gas plants cut their prices to match", "The last plant needed sets one price", "Wind farms are paid extra by law"], "correctIndex": 1, "consequences": ["Prices come from the last unit needed.", "All dispatched plants get the marginal price there.", "This is market design, not a special law."], "explanation": "In these markets, the marginal plant sets the price that dispatched plants receive at that point."}, "proReasoning": "The rule of the day explains it: the next unit of power sets the price for everyone running.", "commonMistake": "Assuming each plant is paid its own cost.", "mentalModel": "One marginal price for all who run."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5ab7f960e0e8$ml$]::text[]),
($ml$f050506b-97ee-5354-a2bc-54a177198c0e$ml$::uuid, $ml$cleanenergy$ml$, 2, 3, $ml${"id": "cleanenergy-d2-c3", "title": "A plant that earns twice", "lessonTitle": "How electricity gets priced", "slot": 3, "type": "decide", "brief": {"headline": "You run a gas plant in PJM that rarely runs. Energy markets pay for power produced, but PJM's capacity market pays for being available, and its latest auction cleared at the cap of $333.44 per MW-day.", "kicker": "Decide: is a rarely used plant still worth keeping?", "fullText": "Your plant runs only on the hottest and coldest days, when prices are high. Most hours, cheaper plants are picked first, because operators dispatch from the lowest cost up.\n\nIn PJM, plants can also earn from the capacity market, which pays them to be ready when needed. The 2027/28 auction cleared at its cap of $333.44 per MW-day, a record driven largely by data center demand. Your board wants to know if the plant still pays its way.", "sources": [{"url": "https://ferc.gov/energy-markets-0", "label": "FERC, what are wholesale electricity markets"}, {"url": "https://www.utilitydive.com/news/pjm-interconnection-capacity-auction-data-center/808264/", "label": "Utility Dive, PJM 2027/28 capacity auction"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What does a capacity market pay your plant for?", "options": ["Selling its power directly to nearby homes", "Being available when the grid needs it", "Every megawatt-hour of power it produces"], "correctIndex": 1, "explanation": "Energy markets pay for output. Capacity markets pay for readiness to supply when needed."}, "numbers": {"kind": "numberSense", "prompt": "About how many dollars per MW-day did PJM's 2027/28 capacity auction clear at?", "min": 0, "max": 1000, "value": 333, "unit": "$", "explanation": "About $333, the cap of $333.44 per MW-day, a record for the third auction in a row."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks why the plant made money in a year it barely ran.", "prompt": "What do you say?", "options": ["It sold power at high prices every hour", "Customers paid it directly for power", "Capacity payments paid it to stay ready"], "correctIndex": 2, "consequences": ["It ran rarely, so energy sales were small.", "It sells into the wholesale market, not to homes.", "Readiness itself earned money in PJM."], "explanation": "In PJM, a plant earns from capacity even when it rarely generates."}, "proReasoning": "Analysts explain earnings by stream. Saying \"capacity carried the year\" shows you know how peakers make money.", "commonMistake": "Explaining a plant's profit with energy sales alone.", "mentalModel": "Split earnings into energy and capacity."}, "invest": {"call": {"kind": "theCall", "situation": "You may buy the plant. Capacity prices hit the cap for three auctions running.", "prompt": "What risk do you check first?", "options": ["How long capacity prices stay this high", "Whether the plant runs every hour", "How cheap its fuel was last year"], "correctIndex": 0, "consequences": ["Much of the value rides on the capacity price.", "A peaker is not meant to run every hour.", "Fuel matters less for a rarely used plant."], "explanation": "For a rarely used plant, capacity revenue drives value. A drop in that price would cut it."}, "proReasoning": "Investors stress-test the biggest revenue line. For a peaker in PJM, that is capacity.", "commonMistake": "Pricing the plant as if record capacity prices last forever.", "mentalModel": "Stress the biggest revenue line."}, "build_startup": {"call": {"kind": "theCall", "situation": "You run a startup with batteries that can respond in seconds.", "prompt": "What does PJM's market design mean for you?", "options": ["Batteries cannot earn on the grid", "Being ready can earn money, not just output", "Only plants that run all day get paid"], "correctIndex": 1, "consequences": ["Flexible supply can earn on both streams.", "Readiness is a product the market pays for.", "Capacity markets pay for availability too."], "explanation": "Markets pay for power when it is needed and for being ready to supply it."}, "proReasoning": "Founders with flexible assets sell readiness, not just energy. Capacity markets turn availability into revenue.", "commonMistake": "Pitching only on energy produced.", "mentalModel": "Readiness is a product."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why anyone pays a plant that sits idle most of the year.", "prompt": "What is the best answer?", "options": ["Because idle plants cost nothing", "Because law forbids closing plants", "So it is there on the hottest days"], "correctIndex": 2, "consequences": ["Staying ready costs money.", "Plants close all the time.", "Supply must meet demand even at peak."], "explanation": "The grid needs enough supply for its peak. Capacity payments keep that supply around."}, "proReasoning": "Think of it like a spare tire. You pay for it all year so it is there when you need it.", "commonMistake": "Assuming idle means useless.", "mentalModel": "You pay for the peak all year."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:19d8c2fbc8d8$ml$]::text[]),
($ml$e8581186-2849-5dfb-96fe-a203aab64392$ml$::uuid, $ml$cleanenergy$ml$, 3, 1, $ml${"id": "cleanenergy-d3-c1", "title": "FERC rewrites the waiting line", "lessonTitle": "Who controls access to the grid", "slot": 1, "type": "apply", "brief": {"headline": "In July 2023, FERC issued Order No. 2023 to fix the interconnection queue. It replaced first-come, first-served studies with yearly cluster studies and made developers prove they are ready.", "kicker": "Apply the queue idea to the rule that reshaped it.", "fullText": "More than 2,000 GW of projects sat in queues at the end of 2022, about 94% of them solar, wind and storage. Waits could reach five years.\n\nOrder No. 2023, issued July 28, 2023, made grid operators study requests in annual clusters. Developers must control 90% of their site to apply and post deposits that rise as studies advance. Operators that miss deadlines face penalties, starting at $1,000 per business day for a late cluster study.", "sources": [{"url": "https://www.klgates.com/Order-No-2023-Interconnection-Reform-is-Finally-Here-9-7-2023", "label": "K&L Gates, FERC Order No. 2023"}, {"url": "https://emp.lbl.gov/publications/queued-2025-edition-characteristics", "label": "Berkeley Lab, Queued Up 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did Order No. 2023 replace?", "options": ["The federal tax credits paid to solar farms", "Serial first-come, first-served studies", "The grid operators that run each region"], "correctIndex": 1, "explanation": "It moved to yearly cluster studies on a first-ready, first-served basis."}, "numbers": {"kind": "numberSense", "prompt": "What share of queued capacity at the end of 2022 was solar, wind and storage?", "min": 0, "max": 100, "value": 94, "unit": "%", "explanation": "About 94% of more than 2,000 GW."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a solar developer. Your manager asks how Order No. 2023 changes your job.", "prompt": "What is the best answer?", "options": ["Nothing, since queues still work the same", "Prove site control and deposits early", "Apply first and figure out the site later"], "correctIndex": 1, "consequences": ["Cluster studies replaced the old serial process.", "90% site control and deposits are now required.", "The order ended easy speculative requests."], "explanation": "The order rewards ready projects. Site control and rising deposits come first."}, "proReasoning": "Developers who frame the job as \"prove readiness early\" fit the new rules. It is first-ready, first-served now.", "commonMistake": "Treating a queue spot as something you grab first and justify later.", "mentalModel": "Ready first, served first."}, "invest": {"call": {"kind": "theCall", "situation": "A developer you might back says it has 10 GW in queues across the US.", "prompt": "What do you ask?", "options": ["How quickly it filed each of those requests", "How many different states it filed requests in", "Which projects have site control and deposits"], "correctIndex": 2, "consequences": ["Speed of filing matters less after the order.", "Breadth says little about odds.", "Readiness now decides who moves forward."], "explanation": "Under the new rules, readiness marks the projects with real odds of moving ahead."}, "proReasoning": "Investors discount queue totals and ask for proof. Deposits and site control separate real projects from placeholders.", "commonMistake": "Taking a gigawatt pipeline at face value.", "mentalModel": "Ask for proof of readiness."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build tools for grid operators. Order No. 2023 adds penalties for late studies.", "prompt": "What need does that create?", "options": ["Finishing interconnection studies on time", "Finding more projects to join queues", "Lobbying to repeal the order"], "correctIndex": 0, "consequences": ["Late cluster studies now cost $1,000 a business day.", "Queues were already overloaded.", "Your product should fit the rule."], "explanation": "Deadlines with penalties make study speed valuable to operators."}, "proReasoning": "Founders read new penalties as new budgets. A fine for slowness makes speed worth paying for.", "commonMistake": "Missing that a regulation can create a buyer.", "mentalModel": "A penalty creates a budget."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that new solar farms wait years to connect. A friend asks why.", "prompt": "What is the best short answer?", "options": ["Farms wait for sunny weather to connect", "Each one needs grid studies before connecting", "Solar panels take years to manufacture"], "correctIndex": 1, "consequences": ["Weather has nothing to do with it.", "Studies check what the grid can handle.", "Panels are made far faster than that."], "explanation": "Every new plant needs permission to connect, and the studies behind it built a long queue."}, "proReasoning": "The bottleneck is the plug, not the panel. Connecting safely takes study.", "commonMistake": "Blaming slow building when the wait is for permission.", "mentalModel": "The plug is the bottleneck."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d88dba41c050$ml$]::text[]),
($ml$6f9970d8-606d-5bc3-bb25-6f4a66415cba$ml$::uuid, $ml$cleanenergy$ml$, 3, 2, $ml${"id": "cleanenergy-d3-c2", "title": "The queue meets the price", "lessonTitle": "Who controls access to the grid", "slot": 2, "type": "connect", "brief": {"headline": "In PJM, a 5,250 MW jump in forecast demand, almost all from data centers, pushed capacity prices to a record. Yet only 13% of capacity that asked to connect from 2000 to 2019 was built.", "kicker": "Connect day 2 and day 3: high prices meet a slow queue.", "fullText": "On day 2 you saw PJM's capacity auction clear at its cap of $333.44 per MW-day. Prices that high signal the grid needs more supply.\n\nDay 3 shows why supply is slow to arrive. About 2,300 GW sat in US queues at the end of 2024. Of the capacity that applied from 2000 to 2019, 77% was withdrawn and only 13% was running by the end of 2024. Median waits passed four years.", "sources": [{"url": "https://www.utilitydive.com/news/pjm-interconnection-capacity-auction-data-center/808264/", "label": "Utility Dive, PJM 2027/28 capacity auction"}, {"url": "https://emp.lbl.gov/publications/queued-2025-edition-characteristics", "label": "Berkeley Lab, Queued Up 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Data centers drove most of a 5,250 MW forecast jump.", "Most queued capacity from 2000 to 2019 got built.", "Median waits rose past four years."], "fakeIndex": 1, "explanation": "Only 13% was built; 77% was withdrawn."}, "numbers": {"kind": "numberSense", "prompt": "What share of capacity that applied from 2000 to 2019 was withdrawn by the end of 2024?", "min": 0, "max": 100, "value": 77, "unit": "%", "explanation": "77% was withdrawn, and only 13% was operating."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked why record capacity prices have not brought a flood of new plants.", "prompt": "What is your answer?", "options": ["Developers ignore price signals", "Capacity prices are actually falling", "New plants are stuck in a slow queue"], "correctIndex": 2, "consequences": ["They respond, but connection takes years.", "Prices hit a record three auctions in a row.", "Waits over four years slow the response."], "explanation": "The price signal is strong, but interconnection limits how fast supply can answer it."}, "proReasoning": "Linking the price signal to the queue shows systems thinking. Demand moves in months; supply moves in years.", "commonMistake": "Assuming markets fix shortages fast when the plug is the bottleneck.", "mentalModel": "Price signals wait in the queue."}, "invest": {"call": {"kind": "theCall", "situation": "You own a running power plant in PJM.", "prompt": "What does the slow queue mean for you?", "options": ["Less new competition, so prices may stay high", "New rivals will connect to the grid within months", "Your plant loses its existing grid connection"], "correctIndex": 0, "consequences": ["Slow entry protects existing plants for now.", "Median waits exceed four years.", "Existing connections are not at risk here."], "explanation": "When new supply is slow to connect, existing plants keep earning high capacity prices longer."}, "proReasoning": "Investors see a slow queue as a moat for running plants. Scarcity pays whoever is already connected.", "commonMistake": "Expecting record prices to fall quickly.", "mentalModel": "A slow queue protects the incumbents."}, "build_startup": {"call": {"kind": "theCall", "situation": "Data centers in PJM want power faster than the queue allows.", "prompt": "What product idea fits?", "options": ["Sell more requests into the queue", "Find sites with spare grid capacity now", "Promise every project a four-year wait"], "correctIndex": 1, "consequences": ["More requests make the queue worse.", "Spare capacity skips much of the wait.", "That is the problem, not the product."], "explanation": "Anything that speeds connection or finds spare capacity saves time and money."}, "proReasoning": "Founders aim at the bottleneck. Speeding up access to the grid is worth more than more applications.", "commonMistake": "Building for the part of the chain that is not stuck.", "mentalModel": "Aim at the bottleneck."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that data centers are pushing up power prices. A friend asks why more plants are not built.", "prompt": "What is the best answer?", "options": ["Nobody wants to build new power plants anymore", "There is simply no room left for more wires", "Most proposed plants never make it through"], "correctIndex": 2, "consequences": ["Thousands of projects are trying.", "The queue, not space, is the main limit.", "Only 13% of older queued capacity was built."], "explanation": "Thousands of projects apply, but most drop out of the queue before they are built."}, "proReasoning": "The numbers tell the story: lots of interest, slow approval, many dropouts.", "commonMistake": "Thinking the shortage is a lack of interest.", "mentalModel": "Lots of plans, few plants."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:cccf1ef2e8fb$ml$]::text[]),
($ml$c0763b53-33a8-53a1-abc0-2ba587da6402$ml$::uuid, $ml$cleanenergy$ml$, 3, 3, $ml${"id": "cleanenergy-d3-c3", "title": "Two sites, one queue", "lessonTitle": "Who controls access to the grid", "slot": 3, "type": "decide", "brief": {"headline": "You lead a solar project and must pick between two sites. One has cheaper land; the other sits near a substation with spare grid capacity. Median queue waits now exceed four years.", "kicker": "Decide: which site gives your project its best odds?", "fullText": "You develop solar farms. Site A has cheaper land but needs major grid upgrades to connect. Site B costs more but sits near a substation that can take more power.\n\nBerkeley Lab found the median time from request to operation doubled to over four years for projects built from 2018 to 2024. Of capacity that applied from 2000 to 2019, only 13% was running by the end of 2024. On the grid, power belongs to whoever controls the connection.", "sources": [{"url": "https://emp.lbl.gov/publications/queued-2025-edition-characteristics", "label": "Berkeley Lab, Queued Up 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does it help or hurt your odds of connecting soon?", "buckets": ["Helps", "Hurts"], "items": [{"text": "A substation with spare capacity nearby", "bucket": 0}, {"text": "Few grid upgrades needed", "bucket": 0}, {"text": "Major new transmission required", "bucket": 1}, {"text": "A crowded queue at that substation", "bucket": 1}], "explanation": "Spare capacity and few upgrades shorten the path. Big upgrades and crowded queues stretch it."}, "numbers": {"kind": "numberSense", "prompt": "About how many years was the median wait from request to operation for projects built 2018 to 2024?", "min": 0, "max": 10, "value": 4, "unit": "years", "explanation": "Over four years, double the under-two-year wait of 2000 to 2007."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks which site you would back and why.", "prompt": "What do you recommend?", "options": ["Site B, for its spare grid capacity", "Site A, for its cheaper land", "Both, and see which queue moves"], "correctIndex": 0, "consequences": ["Connection speed is the real timeline.", "Cheap land with costly upgrades can sink a project.", "Doubling up wastes deposits and time."], "explanation": "Queue position and needed upgrades set the real timeline, so spare capacity wins."}, "proReasoning": "Strong developers lead with grid access, then land. The timeline lives in the queue.", "commonMistake": "Choosing on land price while ignoring upgrade costs.", "mentalModel": "Grid access first, land second."}, "invest": {"call": {"kind": "theCall", "situation": "You are offered stakes in both projects at the same price.", "prompt": "Which do you prefer?", "options": ["Either, since both will surely be built", "Site B, since it is likelier to be built", "Site A, since cheap land means more profit"], "correctIndex": 1, "consequences": ["Most queued projects are never built.", "Odds of completion drive value.", "Upgrade costs can erase land savings."], "explanation": "Only a small share of queued capacity is built, so better odds of connecting matter most."}, "proReasoning": "Investors weigh the odds of completion before the margins. A cheap project that never connects earns nothing.", "commonMistake": "Assuming a queued project will be built.", "mentalModel": "Odds before margins."}, "build_startup": {"call": {"kind": "theCall", "situation": "Developers keep picking sites without knowing where spare grid capacity is.", "prompt": "What could your startup offer?", "options": ["Cheaper land listings for solar", "Faster panel shipping", "Maps of spare capacity by substation"], "correctIndex": 2, "consequences": ["Land is not the bottleneck.", "Panels are not what holds projects up.", "Finding spare capacity saves years."], "explanation": "Waits now top four years. Tools that find spare capacity save time and money."}, "proReasoning": "Founders sell time saved. Showing where the grid has room cuts years from a project.", "commonMistake": "Solving a cheap problem when an expensive one sits next to it.", "mentalModel": "Sell the years you save."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why a solar farm near a busy substation might wait longer than one in a field.", "prompt": "What's the likely reason?", "options": ["Spare grid capacity, not distance, sets the wait", "Busy areas near cities always connect faster", "Open fields get stronger sunshine all year round"], "correctIndex": 0, "consequences": ["A full substation needs upgrades first.", "Busy areas can be the most crowded.", "Sunshine does not change the queue."], "explanation": "What matters is whether the local grid has room. A crowded substation can mean a longer wait."}, "proReasoning": "Think of grid capacity like seats on a bus. A nearby full bus is slower than a farther empty one.", "commonMistake": "Assuming closer to the city means faster.", "mentalModel": "Room on the grid sets the wait."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:50fec683503f$ml$]::text[]),
($ml$24da57d8-dba0-5e14-abd3-fcf1d86dc838$ml$::uuid, $ml$cleanenergy$ml$, 4, 1, $ml${"id": "cleanenergy-d4-c1", "title": "What the US built in 2025", "lessonTitle": "The numbers behind the US power mix", "slot": 1, "type": "apply", "brief": {"headline": "In August 2025, EIA said US developers planned a record 64 GW of new power capacity for the year. Solar made up about 33 GW of it, a little over half, while 8.7 GW of plants were set to retire.", "kicker": "Apply the mix: what is being added versus what makes power today?", "fullText": "EIA's tally showed 12 GW of solar added in the first half of 2025 and 21 GW more planned for the second half. Battery storage made up 26% of first-half additions. Wind, batteries and gas made up nearly all the rest.\n\nThe 2025 generation mix still leaned on older plants: natural gas made about 41% of US power, nuclear 18% and coal 17%. New capacity changes the mix only as it runs, year after year.", "sources": [{"url": "https://www.eia.gov/todayinenergy/detail.php?id=64586", "label": "EIA, Today in Energy, 2025 capacity additions (Aug 2025)"}, {"url": "https://www.eia.gov/energyexplained/electricity/electricity-in-the-us.php", "label": "EIA, electricity in the US"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which source led US capacity additions planned for 2025?", "options": ["Solar, at about half of the total", "Natural gas, at about two-thirds", "Coal, at about a quarter of it"], "correctIndex": 0, "explanation": "Solar was about 33 GW of 64 GW planned, a little over half."}, "numbers": {"kind": "numberSense", "prompt": "How many GW of solar did EIA expect the US to add in 2025?", "min": 0, "max": 100, "value": 33, "unit": "GW", "explanation": "About 33 GW: 12 GW in the first half and 21 GW planned for the second."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks what most new US power capacity looked like in 2025.", "prompt": "Which answer is accurate?", "options": ["Mostly coal plants coming back online", "Mostly large new nuclear reactors", "Mostly solar, with batteries and wind"], "correctIndex": 2, "consequences": ["Coal was retiring, not being added.", "No large reactors came online in 2025.", "Solar was about half of 64 GW planned."], "explanation": "Solar led, with batteries, wind and gas making up nearly all the rest."}, "proReasoning": "Quote both views: additions led by solar, generation led by gas. Knowing the difference shows you read the data well.", "commonMistake": "Confusing what is being built with what makes most power today.", "mentalModel": "Additions and generation tell two stories."}, "invest": {"call": {"kind": "theCall", "situation": "A fund pitches you a gas turbine maker as the main play on new US capacity.", "prompt": "What does the 2025 data suggest?", "options": ["Solar and batteries led additions", "Gas made up most new capacity", "New capacity stopped growing"], "correctIndex": 0, "consequences": ["Solar alone was about half of planned additions.", "Gas was one part of the rest.", "64 GW planned was a record."], "explanation": "Additions were led by solar, with batteries a large share. Gas was only part of the remainder."}, "proReasoning": "Investors check where new capacity actually goes. In 2025 the build was mostly solar and storage.", "commonMistake": "Assuming today's biggest fuel gets most new investment.", "mentalModel": "Follow the build, not the legacy mix."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup can sell to one kind of new power project this year.", "prompt": "Which offers the most new projects?", "options": ["Big hydro dams, rarely built today", "Solar farms, about half of 2025 additions", "Coal plants, which were mostly retiring"], "correctIndex": 1, "consequences": ["Few new dams are being built.", "Most new sites are solar, so most buyers are too.", "Coal was retiring 8.7 GW of plants."], "explanation": "Solar made up about half of planned additions, so most new project buyers build solar."}, "proReasoning": "Founders follow the volume of new projects. More sites means more buyers for tools.", "commonMistake": "Selling to the shrinking part of the market.", "mentalModel": "Sell where the new projects are."}, "curiosity": {"call": {"kind": "theCall", "situation": "If solar is half of new capacity, why does gas still make the most power?", "prompt": "What's the best explanation?", "options": ["Solar panels stop working after only a year or two", "Gas plants are mostly brand new builds from 2025", "Old gas plants still run and new solar adds slowly"], "correctIndex": 2, "consequences": ["Panels last for decades.", "Most gas plants were built years ago.", "The existing fleet changes over many years."], "explanation": "A year of additions is small next to the whole fleet, which is why gas still makes about 41% of power."}, "proReasoning": "Think of the fleet like a library. New books arrive each year, but most of the shelf is old.", "commonMistake": "Expecting one year of building to flip the mix.", "mentalModel": "New capacity moves the mix slowly."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:31929ba42230$ml$]::text[]),
($ml$9bb09ea5-ca49-5b55-aa58-afbc2a015c70$ml$::uuid, $ml$cleanenergy$ml$, 4, 2, $ml${"id": "cleanenergy-d4-c2", "title": "The mix and the queue", "lessonTitle": "The numbers behind the US power mix", "slot": 2, "type": "connect", "brief": {"headline": "In 2025, wind and solar made about 18% of US power, more than coal's 17%. Gas still led at 41%, and nuclear made 18%.", "kicker": "Connect day 3 and day 4: the queue hints at tomorrow's mix.", "fullText": "EIA reports that the US generated about 4.43 trillion kWh in 2025. Natural gas supplied about 41%, nuclear 18%, coal 17%, wind 11%, solar 7% and hydropower 6%.\n\nOn day 3 you saw the queue: about 2,300 GW waiting at the end of 2024. Most of it is solar, wind and storage. Only part will ever connect, but what gets through shapes the mix to come.", "sources": [{"url": "https://www.eia.gov/energyexplained/electricity/electricity-in-the-us.php", "label": "EIA, electricity in the US"}, {"url": "https://emp.lbl.gov/publications/queued-2025-edition-characteristics", "label": "Berkeley Lab, Queued Up 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Did it make more or less than 15% of US power in 2025?", "buckets": ["More than 15%", "Less than 15%"], "items": [{"text": "Natural gas", "bucket": 0}, {"text": "Nuclear", "bucket": 0}, {"text": "Coal", "bucket": 0}, {"text": "Wind", "bucket": 1}, {"text": "Solar", "bucket": 1}, {"text": "Hydropower", "bucket": 1}], "explanation": "Gas 41%, nuclear 18%, coal 17%. Wind 11%, solar 7% and hydro 6% each made less than 15%."}, "numbers": {"kind": "numberSense", "prompt": "What share of US power did wind and solar make together in 2025?", "min": 0, "max": 60, "value": 18, "unit": "%", "explanation": "About 18%: wind 11% plus solar 7%, just ahead of coal at 17%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks you to sum up the 2025 US power mix in one line.", "prompt": "What do you say?", "options": ["Gas leads; wind and solar now pass coal", "Coal still makes most US electricity", "Solar alone makes most US electricity"], "correctIndex": 0, "consequences": ["Gas 41%, wind and solar 18%, coal 17%.", "Coal made about 17%.", "Solar made about 7%."], "explanation": "Gas led at 41%. Wind and solar together, at about 18%, edged past coal."}, "proReasoning": "Have the five numbers ready: gas 41, nuclear 18, coal 17, wind 11, solar 7. It anchors any energy conversation.", "commonMistake": "Rounding the story to \"renewables are winning\" without the numbers.", "mentalModel": "Quote the mix, then the trend."}, "invest": {"call": {"kind": "theCall", "situation": "You weigh whether coal's share will rebound.", "prompt": "What does the queue suggest?", "options": ["The queue is empty, so the mix is fixed", "New supply waiting is mostly solar, wind, storage", "Coal plants dominate the queue of new requests"], "correctIndex": 1, "consequences": ["About 2,300 GW is waiting.", "What connects next is mostly clean supply.", "Coal is a tiny share of new requests."], "explanation": "The queue is mostly solar, wind and storage, pointing the mix further that way."}, "proReasoning": "Investors read the queue as a preview of the mix. It shows where developers are placing bets.", "commonMistake": "Treating today's mix as tomorrow's.", "mentalModel": "The queue previews the mix."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build forecasting software for grid operators.", "prompt": "What trend should it handle well?", "options": ["More coal plants coming back onto the grid", "Fewer kinds of power plants to keep track of", "More output that varies with sun and wind"], "correctIndex": 2, "consequences": ["Coal is shrinking.", "The mix is getting more varied, not less.", "Wind and solar at 18% and rising need forecasting."], "explanation": "Wind and solar output varies with weather. As their share grows, forecasting matters more."}, "proReasoning": "Founders build for where the mix is going. More weather-driven power means more need for forecasts.", "commonMistake": "Building for a grid that is disappearing.", "mentalModel": "Build for the coming mix."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says renewables make most US power now.", "prompt": "What's closer to the truth?", "options": ["Wind and solar made about 18% in 2025", "Wind and solar made over 60% in 2025", "Wind and solar made under 2% in 2025"], "correctIndex": 0, "consequences": ["They passed coal but trail gas by far.", "Gas alone made 41%.", "They made far more than 2%."], "explanation": "Wind 11% and solar 7% made about 18%, ahead of coal but well behind gas."}, "proReasoning": "A milestone is not a takeover. Passing coal is real; overtaking gas is still far off.", "commonMistake": "Overstating or understating the share without checking.", "mentalModel": "Passed coal, still behind gas."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7eb5dab36068$ml$]::text[]),
($ml$68362ab9-4cab-5a3c-8706-9118affcb150$ml$::uuid, $ml$cleanenergy$ml$, 4, 3, $ml${"id": "cleanenergy-d4-c3", "title": "Pricing power for a new campus", "lessonTitle": "The numbers behind the US power mix", "slot": 3, "type": "decide", "brief": {"headline": "You buy power for a company building a campus in PJM. Gas makes about 41% of US power, and PJM's capacity price set a record for the third auction in a row.", "kicker": "Decide: what does the mix tell you about your power costs?", "fullText": "You must budget electricity for a new campus. Gas is the biggest US fuel, at about 41% of 2025 generation, so gas prices often move power prices.\n\nPJM's capacity price set a record for the third auction in a row, signalling a tight grid. Data centers drove a 5,250 MW jump in its demand forecast. On the grid, the mix sets the price, and the mix is shifting.", "sources": [{"url": "https://www.eia.gov/energyexplained/electricity/electricity-in-the-us.php", "label": "EIA, electricity in the US"}, {"url": "https://www.utilitydive.com/news/pjm-interconnection-capacity-auction-data-center/808264/", "label": "Utility Dive, PJM 2027/28 capacity auction"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Gas made about 41% of US power in 2025.", "PJM's capacity price fell to a record low.", "Data centers drove a 5,250 MW forecast jump."], "fakeIndex": 1, "explanation": "PJM's capacity price set a record high for the third auction in a row."}, "numbers": {"kind": "numberSense", "prompt": "What share of US electricity came from nuclear in 2025?", "min": 0, "max": 60, "value": 18, "unit": "%", "explanation": "About 18%, tied with wind and solar combined."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CFO asks what most likely drives your campus's energy price.", "prompt": "What do you say?", "options": ["The number of states in PJM", "Gas prices and tight capacity in PJM", "The share of solar on the roof"], "correctIndex": 1, "consequences": ["Region size does not set your price.", "Gas often sets the price; capacity is at records.", "Rooftop solar is a small part of supply."], "explanation": "Gas is the leading fuel and often marginal, and PJM capacity is scarce."}, "proReasoning": "Buyers who link price to fuel and scarcity give clear budgets. Gas and capacity are the two levers.", "commonMistake": "Budgeting from last year's bill without asking what drives it.", "mentalModel": "Price follows fuel and scarcity."}, "invest": {"call": {"kind": "theCall", "situation": "You own a nuclear plant in PJM. Capacity prices are at records.", "prompt": "What does that mean for it?", "options": ["Lower revenue, since prices are capped", "No change, since nuclear runs anyway", "Higher revenue for staying available"], "correctIndex": 2, "consequences": ["The cap is still a record price.", "Capacity revenue comes on top of energy.", "Record capacity prices pay plants to be ready."], "explanation": "Record capacity prices mean more revenue for existing plants in PJM."}, "proReasoning": "Investors see scarcity as revenue for plants already running. Record capacity prices flow straight to them.", "commonMistake": "Ignoring capacity revenue for a plant that runs all the time.", "mentalModel": "Scarcity pays the incumbents."}, "build_startup": {"call": {"kind": "theCall", "situation": "Large buyers in PJM face rising costs from a tight grid.", "prompt": "What could your startup sell them?", "options": ["Ways to cut use at the costliest hours", "More power plants in other countries", "Advice to ignore their power bills"], "correctIndex": 0, "consequences": ["Cutting peak use saves the most in a tight grid.", "Foreign plants do not serve PJM.", "Ignoring costs is not a product."], "explanation": "When the grid is tight, the costliest hours are where savings live."}, "proReasoning": "Founders aim at the most expensive hours. That is where a tight grid hurts buyers most.", "commonMistake": "Selling average savings when peaks drive the bill.", "mentalModel": "Savings live in the peak hours."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why would gas prices matter for your electric bill?", "prompt": "What's the link?", "options": ["Gas companies send out your electric bills too", "Gas makes the most US power and often sets prices", "Your home burns gas to make its own electricity"], "correctIndex": 1, "consequences": ["Billing and fuel are separate.", "At 41% of power, gas plants are often marginal.", "Plants burn gas; your outlets do not."], "explanation": "Gas made about 41% of US power in 2025, so its price feeds into electricity prices."}, "proReasoning": "Follow the biggest fuel. When it gets pricier, power usually does too.", "commonMistake": "Thinking electricity and gas prices are unrelated.", "mentalModel": "The biggest fuel steers the price."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d570757585e2$ml$]::text[]),
($ml$1a3b3edb-026c-54b5-8117-b5ed24d6c6fa$ml$::uuid, $ml$cleanenergy$ml$, 5, 1, $ml${"id": "cleanenergy-d5-c1", "title": "The Christmas freeze in PJM", "lessonTitle": "The rule that keeps the lights on", "slot": 1, "type": "apply", "brief": {"headline": "On December 24, 2022, Winter Storm Elliott knocked out nearly 46,000 MW of PJM's generation. Demand had just peaked near 135,000 MW, about 10% above forecast.", "kicker": "Apply the balance rule to a holiday storm.", "fullText": "Forced outages in PJM started near 12,000 MW on December 23 and grew to nearly 46,000 MW by the next morning. More than 90% came with no notice or less than an hour's warning.\n\nPJM called on reserves and demand response, declared a maximum generation emergency, and asked the public to conserve power for the first time since the 2014 Polar Vortex. It also obtained a federal order to keep certain units available.", "sources": [{"url": "https://insidelines.pjm.com/pjm-operated-reliably-throughout-winter-storm-challenges/", "label": "PJM Inside Lines, Winter Storm Elliott"}]}, "evidence": {"kind": "buildChain", "prompt": "Put PJM's response in order.", "steps": ["PJM issues cold weather alerts days ahead", "Plants trip offline as temperatures plunge", "PJM calls on reserves and demand response", "PJM asks the public to conserve power"], "explanation": "Alerts came first. As outages hit, PJM used its emergency tools, then made its first public call for conservation since 2014."}, "numbers": {"kind": "numberSense", "prompt": "About how many GW of PJM generation were in forced outages on the morning of December 24, 2022?", "min": 0, "max": 100, "value": 46, "unit": "GW", "explanation": "Nearly 46,000 MW, or about 46 GW."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a grid operations interview, you are asked what made Elliott hard to manage.", "prompt": "What is the strongest answer?", "options": ["Most outages came with almost no warning", "Demand fell far below the forecast", "PJM had too much generation online"], "correctIndex": 0, "consequences": ["Over 90% came with under an hour's notice.", "Demand ran about 10% above forecast.", "PJM was short of generation, not long."], "explanation": "Surprise outages plus higher-than-forecast demand squeezed the balance."}, "proReasoning": "Operators talk about surprise and margin. Elliott combined sudden outages with demand above forecast.", "commonMistake": "Describing the storm without the numbers that made it hard.", "mentalModel": "Surprise outages, thin margins."}, "invest": {"call": {"kind": "theCall", "situation": "You own gas plants in PJM. Several failed to run during Elliott.", "prompt": "What risk does the storm reveal?", "options": ["Prices staying too low all winter", "Failing to perform when the grid needs you", "Too many customers buying your power"], "correctIndex": 1, "consequences": ["Storm prices are not the risk here.", "Plants are paid to be ready; failing hurts.", "Demand was the grid's problem, not yours."], "explanation": "Capacity markets pay for readiness. A plant that trips in a storm undercuts what it was paid for."}, "proReasoning": "Investors stress-test plants for the worst days. Readiness pays only if the plant shows up.", "commonMistake": "Valuing a plant on normal days only.", "mentalModel": "Readiness pays only if you run."}, "build_startup": {"call": {"kind": "theCall", "situation": "Most Elliott outages came with under an hour's notice.", "prompt": "What product could help operators?", "options": ["Better holiday lighting displays", "Cheaper summer cooling tools", "Early warning of plants likely to fail"], "correctIndex": 2, "consequences": ["Lighting does not help grid balance.", "Summer tools miss a winter problem.", "More warning means more time to act."], "explanation": "Operators struggled because failures came fast. Earlier warning gives them time."}, "proReasoning": "Founders turn surprise into lead time. An hour of warning can decide how a storm ends.", "commonMistake": "Solving the season that already works.", "mentalModel": "Turn surprise into warning."}, "curiosity": {"call": {"kind": "theCall", "situation": "PJM asked people to save power on Christmas Eve 2022.", "prompt": "Why would that help?", "options": ["Less demand helps match short supply", "It gave power plants a holiday break", "It lowered everyone's bills by law"], "correctIndex": 0, "consequences": ["Supply must match demand every second.", "Plants were needed more than ever.", "Conservation was about balance, not bills."], "explanation": "With supply short, cutting demand helps keep the two balanced."}, "proReasoning": "When supply drops, demand is the other lever. Saving power buys time.", "commonMistake": "Thinking conservation appeals are only about saving money.", "mentalModel": "Cut demand when supply drops."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9617d916b991$ml$]::text[]),
($ml$49b11cef-8fa6-56a0-9a3a-6c62908ed90c$ml$::uuid, $ml$cleanenergy$ml$, 5, 2, $ml${"id": "cleanenergy-d5-c2", "title": "The operator's hardest call", "lessonTitle": "The rule that keeps the lights on", "slot": 2, "type": "connect", "brief": {"headline": "In February 2021, ERCOT lost 48.6% of its generation at the peak of the outages. It ordered 20,000 MW of rolling blackouts, the largest controlled load shed in US history.", "kicker": "Connect day 1 and day 5: the operator's job is the balance.", "fullText": "On day 1 you met ERCOT, which runs most of the Texas grid. Its job is to keep supply matching demand every second.\n\nDuring Winter Storm Uri, plants failed faster than demand could fall. ERCOT cut power to customers on purpose to protect the system. It came within 4 minutes and 37 seconds of a total collapse, which would have required a black start and left Texas dark for an indeterminate time.", "sources": [{"url": "https://katv.com/news/nation-world/texas-grid-operator-state-was-minutes-away-from-grid-crash-black-start", "label": "KATV, ERCOT minutes from collapse"}, {"url": "https://ferc.gov/news-events/news/final-report-february-2021-freeze-underscores-winterization-recommendations", "label": "FERC, final report on the February 2021 freeze"}, {"url": "https://www.eia.gov/energyexplained/electricity/delivery-to-consumers.php", "label": "EIA, delivery to consumers"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why did ERCOT cut power to millions on purpose?", "options": ["To keep the whole grid from collapsing", "To lower prices for its customers", "To repair lines damaged by snow"], "correctIndex": 0, "explanation": "With supply far short, cutting load kept the system in balance and avoided a black start."}, "numbers": {"kind": "numberSense", "prompt": "What share of its generation had ERCOT lost at the peak of the outages?", "min": 0, "max": 80, "value": 49, "unit": "%", "explanation": "48.6%, nearly half the fleet."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks how you would describe ERCOT's choice to shed 20,000 MW.", "prompt": "What is your answer?", "options": ["A pricing decision to cut costs", "A painful step that saved the grid", "A sign ERCOT ignored the balance"], "correctIndex": 1, "consequences": ["It was about reliability, not cost.", "It kept the system from a total collapse.", "Balance was exactly what it protected."], "explanation": "Load shed is the last tool to protect balance and avoid a black start."}, "proReasoning": "Grid professionals frame load shed as a last resort that works. Collapse would have been far worse.", "commonMistake": "Calling rolling blackouts a failure of the operator by default.", "mentalModel": "Shedding load protects the whole."}, "invest": {"call": {"kind": "theCall", "situation": "You weigh investing in a Texas grid operator's suppliers after Uri.", "prompt": "What spending would you expect to rise?", "options": ["Building more holiday decorations", "Cutting all reliability budgets", "Winterizing plants and fuel supply"], "correctIndex": 2, "consequences": ["Not a grid spending category.", "Uri pushed budgets the other way.", "Freezing and fuel caused about 76% of failures."], "explanation": "Freezing and fuel problems caused most failures, so winterization spending rises."}, "proReasoning": "Investors follow the post-crisis fix. After Uri, cold-weather protection became required.", "commonMistake": "Expecting nothing to change after a near collapse.", "mentalModel": "Crises create required spending."}, "build_startup": {"call": {"kind": "theCall", "situation": "ERCOT had to cut whole neighborhoods to balance the grid.", "prompt": "What could make that less painful?", "options": ["Customers who can cut use on request", "More power exports out of Texas", "Higher retail prices all year long"], "correctIndex": 0, "consequences": ["Flexible demand reduces forced blackouts.", "Texas needed more power, not less.", "Price alone did not prevent Uri."], "explanation": "If enough demand can drop on request, fewer customers must be cut by force."}, "proReasoning": "Founders see flexible demand as a softer lever than blackouts. Volunteers beat forced cuts.", "commonMistake": "Ignoring demand as a tool for balance.", "mentalModel": "Flexible demand softens the cut."}, "curiosity": {"call": {"kind": "theCall", "situation": "What would a total collapse have meant for Texas?", "prompt": "Which is right?", "options": ["Power from other states within minutes", "A black start and an unknown wait for power", "A short flicker before lights returned"], "correctIndex": 1, "consequences": ["Texas is mostly on its own grid.", "Restarting a whole grid from zero takes long.", "Collapse is far worse than a flicker."], "explanation": "A collapse would have required a black start, leaving Texas without power for an indeterminate time."}, "proReasoning": "Minutes from weeks in the dark: that is why operators accept rolling blackouts.", "commonMistake": "Thinking a grid can simply be switched back on.", "mentalModel": "Collapse means starting from zero."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c0a823640af5$ml$]::text[]),
($ml$c4162677-f1b7-5191-93c0-2d7b0e71eb7b$ml$::uuid, $ml$cleanenergy$ml$, 5, 3, $ml${"id": "cleanenergy-d5-c3", "title": "Winterize or wait", "lessonTitle": "The rule that keeps the lights on", "slot": 3, "type": "decide", "brief": {"headline": "You run a gas plant in Texas. Freezing and fuel problems caused about 76% of plant failures in the 2021 storm, and in 2023 FERC approved standards requiring cold-weather protection.", "kicker": "Decide: how do you prepare the plant for the next freeze?", "fullText": "FERC's final report on the February 2021 freeze found that freezing and fuel problems caused about 76% of plant failures. ERCOT lost 48.6% of its generation and had to shed 20,000 MW.\n\nIn 2023, FERC approved reliability standards requiring generators to protect plants against freezing. The upgrades cost money, but on the grid, supply must meet demand every second, or someone loses power.", "sources": [{"url": "https://ferc.gov/news-events/news/final-report-february-2021-freeze-underscores-winterization-recommendations", "label": "FERC, final report on the February 2021 freeze"}, {"url": "https://www.power-eng.com/business/policy-and-regulation/two-years-after-winter-storm-uri-ferc-approves-new-cold-weather-rules/", "label": "Power Engineering, FERC cold weather rules"}, {"url": "https://katv.com/news/nation-world/texas-grid-operator-state-was-minutes-away-from-grid-crash-black-start", "label": "KATV, ERCOT minutes from collapse"}]}, "evidence": {"kind": "faceOff", "prompt": "What caused most plant failures in the 2021 Texas storm?", "left": {"name": "Freezing and fuel problems", "note": "About 76% of failures"}, "right": {"name": "Wind turbines", "note": "A common claim at the time"}, "correctIndex": 0, "explanation": "FERC found freezing and fuel problems caused about 76% of failures across plant types."}, "numbers": {"kind": "numberSense", "prompt": "What share of plant failures in the 2021 storm came from freezing and fuel problems?", "min": 0, "max": 100, "value": 76, "unit": "%", "explanation": "About 76%, per FERC's final report."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are the plant engineer. Your boss asks for one priority before winter.", "prompt": "What do you pick?", "options": ["Paint the plant so it looks better to visitors", "Cut staff during the cold months to save money", "Protect equipment and fuel lines from freezing"], "correctIndex": 2, "consequences": ["Paint does not keep a plant running.", "Fewer staff raises the risk.", "That targets the cause of most failures."], "explanation": "Freezing and fuel caused most failures, and new standards require protection."}, "proReasoning": "Engineers who tie priorities to the failure data get budgets approved. Freeze protection is the top item.", "commonMistake": "Spreading money across everything instead of the main cause.", "mentalModel": "Fix what failed most."}, "invest": {"call": {"kind": "theCall", "situation": "Winterization will cost your plant millions. Your partner wants to skip it.", "prompt": "What do you argue?", "options": ["It is required, and failing costs more", "Skip it and hope winters stay mild", "Sell the plant before winter"], "correctIndex": 0, "consequences": ["The 2023 standards require cold-weather prep.", "Hope is not a plan against rules or storms.", "A plant without prep is worth less."], "explanation": "The rules require it, and plants that run through extreme weather earn when others fail."}, "proReasoning": "Investors see winterization as both compliance and an edge. The plant that runs in a freeze earns the most.", "commonMistake": "Treating required reliability spending as optional.", "mentalModel": "Reliability spending is a moat."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell sensors that warn when plant equipment is about to freeze.", "prompt": "What is your strongest pitch?", "options": ["Replace all plant operators with AI", "Help meet the new cold-weather standards", "Make plants run cooler in summer"], "correctIndex": 1, "consequences": ["Grid operators cannot risk unproven claims.", "Compliance gives buyers a reason to act now.", "This is a winter problem."], "explanation": "New standards require freeze protection, so tools that help comply have ready buyers."}, "proReasoning": "Founders attach to a rule buyers must meet. A standard turns a nice-to-have into a must.", "commonMistake": "Overpromising to buyers who cannot risk failure.", "mentalModel": "Sell compliance, then reliability."}, "curiosity": {"call": {"kind": "theCall", "situation": "You heard frozen wind turbines caused the Texas blackouts.", "prompt": "What did FERC find?", "options": ["Wind turbines caused nearly all failures", "No plants failed at all", "Most failures came from freezing and fuel"], "correctIndex": 2, "consequences": ["Failures came from many plant types.", "ERCOT lost 48.6% of its generation.", "About 76% of failures were freezing and fuel."], "explanation": "FERC found freezing and fuel problems caused about 76% of failures across plant types."}, "proReasoning": "Check the report before the headline. The failures were broad, and cold was the common cause.", "commonMistake": "Blaming one technology for a system-wide failure.", "mentalModel": "Read the report, not the rumor."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:2abb77e4bc9c$ml$]::text[]),
($ml$484e3f8a-b9e2-53de-9005-df0a3d344cdd$ml$::uuid, $ml$cleanenergy$ml$, 6, 1, $ml${"id": "cleanenergy-d6-c1", "title": "Lightning over England", "lessonTitle": "The day Spain went dark", "slot": 1, "type": "apply", "brief": {"headline": "On August 9, 2019, a lightning strike was followed by the loss of the Hornsea One offshore wind farm and the Little Barford gas plant. More than a million people in Great Britain lost power.", "kicker": "Apply the Iberia lesson to an earlier blackout.", "fullText": "Ofgem found that both large plants failed to stay connected after the strike, and about 150 MW of smaller distributed generation also dropped off. Local network operators then cut customers to protect the system.\n\nHornsea One and RWE, which runs Little Barford, each agreed to pay £4.5 million. UK Power Networks paid £1.5 million after reconnecting customers without being asked by the system operator. The total came to £10.5 million.", "sources": [{"url": "https://ofgem.gov.uk/publications/companies-pay-ps105-million-over-9-august-power-cut", "label": "Ofgem, companies pay £10.5 million over 9 August power cut"}]}, "evidence": {"kind": "faceOff", "prompt": "What did Ofgem say the two big plants did wrong?", "left": {"name": "Did not stay connected", "note": "Both tripped after the strike"}, "right": {"name": "Made too much power", "note": "Flooded the grid"}, "correctIndex": 0, "explanation": "Ofgem found Hornsea One and Little Barford did not remain connected after the lightning strike."}, "numbers": {"kind": "numberSense", "prompt": "About how many MW of small distributed generation also dropped off?", "min": 0, "max": 500, "value": 150, "unit": "MW", "explanation": "About 150 MW, on top of the two large plants."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a grid engineering interview, you are asked what lesson August 2019 teaches.", "prompt": "What is your answer?", "options": ["Wind farms should never connect", "Plants must ride through faults, not trip", "Lightning makes blackouts unavoidable"], "correctIndex": 1, "consequences": ["A gas plant also tripped.", "Staying connected is what failed that day.", "Grids are built to survive strikes."], "explanation": "The failure was that big plants did not stay connected after a routine disturbance."}, "proReasoning": "Engineers talk about ride-through and protection settings. That is where August 2019 went wrong.", "commonMistake": "Blaming the weather when the response was the problem.", "mentalModel": "Ride through the fault."}, "invest": {"call": {"kind": "theCall", "situation": "You own a stake in a wind farm. Regulators are tightening rules after a blackout.", "prompt": "What cost should you expect?", "options": ["A ban on selling wind power", "Higher prices for the power it sells", "Upgrades so it stays connected in faults"], "correctIndex": 2, "consequences": ["Rules target behavior, not bans.", "Rules add costs; they do not raise prices.", "Compliance means better control and settings."], "explanation": "Plants that trip off pay penalties, so owners invest to stay connected."}, "proReasoning": "Investors price in stability rules. Each blackout leads to tougher standards for plants.", "commonMistake": "Assuming a blackout fine is a one-off cost.", "mentalModel": "Blackouts write new rules."}, "build_startup": {"call": {"kind": "theCall", "situation": "About 150 MW of small generators dropped off unseen on August 9.", "prompt": "What gap could your startup fill?", "options": ["Seeing what small generators do live", "Selling more lightning rods to homes", "Building bigger gas plants faster"], "correctIndex": 0, "consequences": ["Operators lack visibility of small generators.", "Lightning was only the trigger.", "Size was not the problem."], "explanation": "Small distributed generation is hard for operators to see. Monitoring fills the gap."}, "proReasoning": "Founders look for what operators cannot see. Visibility of small generators keeps coming up after blackouts.", "commonMistake": "Fixing the trigger instead of the weak spot.", "mentalModel": "Make the invisible visible."}, "curiosity": {"call": {"kind": "theCall", "situation": "How can one lightning strike black out a million people?", "prompt": "What's the best answer?", "options": ["Lightning drained all the batteries", "Big plants tripped, and supply fell short", "The strike hit every home at once"], "correctIndex": 1, "consequences": ["Batteries were not the issue.", "Losing two plants broke the balance.", "One strike hit one line."], "explanation": "The strike was routine. Two big plants dropping off broke the balance, so customers were cut."}, "proReasoning": "Blackouts usually cascade from a small trigger. The response matters more than the spark.", "commonMistake": "Thinking the trigger alone explains the outage.", "mentalModel": "Small spark, big cascade."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f70f85ce2a38$ml$]::text[]),
($ml$ded26ec1-195d-5545-b53c-be8cbbbe3097$ml$::uuid, $ml$cleanenergy$ml$, 6, 2, $ml${"id": "cleanenergy-d6-c2", "title": "Two ways to lose a grid", "lessonTitle": "The day Spain went dark", "slot": 2, "type": "connect", "brief": {"headline": "Texas in 2021 lost nearly half its generation to the cold. Spain and Portugal in 2025 lost 15 GW in about five seconds as voltage rose and plants shut off to protect themselves.", "kicker": "Connect day 5 and day 6: balance and control both keep the lights on.", "fullText": "On day 5, Texas ran short of supply: ERCOT lost 48.6% of its generation and shed 20,000 MW to save the grid.\n\nOn day 6, Iberia had power but lost control. On April 28, 2025, voltage rose fast and generators disconnected to protect themselves, each trip making the next more likely. Both countries went dark. Most of mainland Spain was back that evening, and Portugal restored all 6.4 million customers.", "sources": [{"url": "https://katv.com/news/nation-world/texas-grid-operator-state-was-minutes-away-from-grid-crash-black-start", "label": "KATV, ERCOT minutes from collapse"}, {"url": "https://www.pv-tech.org/combination-of-voltage-and-oscillation-caused-iberian-blackout-says-entso-e-report/", "label": "PV Tech, ENTSO-E report on the Iberian blackout"}, {"url": "https://brusselstimes.com/world/1555964/99-of-electricity-restored-in-spain-after-major-blackout/", "label": "Brussels Times, 99% of electricity restored in Spain"}, {"url": "https://www.renewableenergyworld.com/power-grid/outage-management/final-entso-e-report-sheds-light-on-multiple-factors-that-caused-iberia-blackout", "label": "Renewable Energy World, final ENTSO-E report on the Iberia blackout"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the Iberian cascade in order.", "steps": ["Grid voltage starts rising fast", "Generators shut off to protect themselves", "Each trip makes the next more likely", "Spain and Portugal lose power"], "explanation": "Voltage rose, plants tripped, and each disconnection pushed others over. That is a cascading failure."}, "numbers": {"kind": "numberSense", "prompt": "About how many GW vanished from the Iberian grid in roughly five seconds?", "min": 0, "max": 50, "value": 15, "unit": "GW", "explanation": "About 15 GW, in roughly five seconds."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Asked to compare Texas 2021 and Iberia 2025, what do you say?", "prompt": "Which comparison is sharpest?", "options": ["Both were caused by too much solar", "Both were caused by cyberattacks", "Texas ran short; Iberia lost control"], "correctIndex": 2, "consequences": ["Texas was a freeze; Iberia was control.", "Neither report pointed to an attack.", "One lacked supply, the other voltage control."], "explanation": "Texas lost supply to the cold. Iberia had power but lost voltage control."}, "proReasoning": "Separating supply failures from control failures shows real grid sense. They need different fixes.", "commonMistake": "Lumping every blackout into one cause.", "mentalModel": "Short of power or short of control."}, "invest": {"call": {"kind": "theCall", "situation": "You can fund one fix after these two blackouts.", "prompt": "Which fits Iberia best?", "options": ["Voltage control equipment", "More winterized gas plants", "More rooftop solar panels"], "correctIndex": 0, "consequences": ["Iberia's report pointed at voltage control.", "That fixes Texas, not Iberia.", "More solar does not fix control."], "explanation": "Iberia's final report blamed gaps in voltage control, so that is the fix."}, "proReasoning": "Investors match the fix to the failure. Stability spending targets control, not just supply.", "commonMistake": "Funding more supply for a control problem.", "mentalModel": "Match the fix to the failure."}, "build_startup": {"call": {"kind": "theCall", "situation": "Both blackouts hinged on what happened in seconds or minutes.", "prompt": "What could your startup offer?", "options": ["Longer warranties for panels", "Faster warning of a coming cascade", "Cheaper monthly billing software"], "correctIndex": 1, "consequences": ["Warranties do not help in real time.", "Seconds of warning can stop a cascade.", "Billing does not stop a blackout."], "explanation": "Cascades move fast. Earlier warning gives operators time to act."}, "proReasoning": "Founders build for the critical seconds. That is when blackouts are won or lost.", "commonMistake": "Building tools for the slow parts of the problem.", "mentalModel": "Win the critical seconds."}, "curiosity": {"call": {"kind": "theCall", "situation": "Can a grid with plenty of power still black out?", "prompt": "What's the answer?", "options": ["No, enough power always keeps it up", "Only if every plant breaks at once", "Yes, if it loses voltage control"], "correctIndex": 2, "consequences": ["Iberia proves otherwise.", "A cascade starts with a few trips.", "Iberia had power but lost control."], "explanation": "Stability depends on control, not just on how much power you have."}, "proReasoning": "Remember both rules: match supply and demand, and keep the grid under control.", "commonMistake": "Thinking more power always means more safety.", "mentalModel": "Power is not the same as control."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0963bdd93664$ml$]::text[]),
($ml$3507c2c1-981d-5ba6-9d77-3e50ea4015ab$ml$::uuid, $ml$cleanenergy$ml$, 6, 3, $ml${"id": "cleanenergy-d6-c3", "title": "Swinging voltage on sunny days", "lessonTitle": "The day Spain went dark", "slot": 3, "type": "decide", "brief": {"headline": "You run a grid with lots of solar, and voltage keeps swinging on sunny days. After Iberia, Europe's operators issued 23 recommendations, and Spain now lets renewables help control voltage.", "kicker": "Decide: what do you do before a swing becomes a blackout?", "fullText": "ENTSO-E's final report on the Iberian blackout, released in March 2026, urged better voltage control and coordination. Its president said renewables were not the problem; voltage control was. Some rooftop solar did trip off as voltage rose, and operators could not see some systems reconnect.\n\nSpain changed its rules so renewables can help control voltage. On a modern grid, stability depends on control, not just on how much power you have.", "sources": [{"url": "https://www.pv-tech.org/combination-of-voltage-and-oscillation-caused-iberian-blackout-says-entso-e-report/", "label": "PV Tech, ENTSO-E report on the Iberian blackout"}, {"url": "https://www.renewableenergyworld.com/power-grid/outage-management/final-entso-e-report-sheds-light-on-multiple-factors-that-caused-iberia-blackout", "label": "Renewable Energy World, final ENTSO-E report on the Iberia blackout"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does it strengthen or weaken voltage control?", "buckets": ["Strengthens", "Weakens"], "items": [{"text": "Letting solar plants help control voltage", "bucket": 0}, {"text": "Better coordination between operators", "bucket": 0}, {"text": "Solar systems the operator cannot see", "bucket": 1}, {"text": "Plants that trip off as voltage rises", "bucket": 1}], "explanation": "Control and coordination help. Invisible systems and plants that trip off make swings worse."}, "numbers": {"kind": "numberSense", "prompt": "How many recommendations did the final Iberian blackout report make?", "min": 0, "max": 60, "value": 23, "explanation": "23, centered on voltage control and coordination."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your director asks for your first step on the voltage swings.", "prompt": "What do you propose?", "options": ["Have solar plants help control voltage", "Ban new solar connections for now", "Wait to see if a blackout happens"], "correctIndex": 0, "consequences": ["Spain made this change after Iberia.", "You lose cheap power and fix nothing.", "Iberia showed how fast it spreads."], "explanation": "The fix is better control, including from renewables, not fewer renewables."}, "proReasoning": "Engineers who cite Iberia's fix show they follow the field. Control, not curtailment, was the answer.", "commonMistake": "Treating solar itself as the problem.", "mentalModel": "Add control, not limits."}, "invest": {"call": {"kind": "theCall", "situation": "Grids with more solar need voltage support after Iberia.", "prompt": "Where do you expect spending to grow?", "options": ["Fewer grid control systems to cut costs", "Voltage support and fast grid equipment", "New coal plants to replace the solar farms"], "correctIndex": 1, "consequences": ["More control, not less, is needed.", "Stability equipment is the recommended fix.", "The report did not call for coal."], "explanation": "Grids with more solar need voltage support and fast-acting equipment. That spending will grow."}, "proReasoning": "Investors watch the fixes a report recommends. Stability is becoming its own market.", "commonMistake": "Reading a blackout as a reason to bet against renewables.", "mentalModel": "Stability is a market."}, "build_startup": {"call": {"kind": "theCall", "situation": "Iberia's operators could not see some solar systems reconnect.", "prompt": "What product fills that gap?", "options": ["A new brand of solar panel for rooftops", "Cheaper power meters for every home", "Live monitoring of small solar systems"], "correctIndex": 2, "consequences": ["Panels were not the issue.", "Meters alone do not give live control.", "Visibility was a gap the report flagged."], "explanation": "Monitoring tools for distributed solar fill a gap operators struggled with."}, "proReasoning": "Founders read blackout reports for gaps. Here the gap was visibility of small systems.", "commonMistake": "Building hardware when the gap is information.", "mentalModel": "Read the report for the gap."}, "curiosity": {"call": {"kind": "theCall", "situation": "Did too much solar cause the Iberian blackout?", "prompt": "What did Europe's operators conclude?", "options": ["Gaps in voltage control were the core issue", "Solar alone caused the entire blackout", "A single broken cable caused it all"], "correctIndex": 0, "consequences": ["The report pointed to many factors, led by voltage control.", "Their president said renewables were not the problem.", "The report found many interacting factors."], "explanation": "ENTSO-E blamed many interacting factors, led by gaps in voltage control."}, "proReasoning": "Blackouts rarely have one villain. Iberia was a control failure with many contributors.", "commonMistake": "Picking one cause before the report is out.", "mentalModel": "Many factors, one core gap."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:79b3e9436274$ml$]::text[]),
($ml$53d30a9a-152d-5f5a-9e50-7039f44e1ac7$ml$::uuid, $ml$cleanenergy$ml$, 7, 1, $ml${"id": "cleanenergy-d7-c1", "title": "A nuclear price set for 35 years", "lessonTitle": "Comparing power plants fairly", "slot": 1, "type": "apply", "brief": {"headline": "Britain agreed to pay Hinkley Point C £92.50 per MWh in 2012 prices for 35 years. When the deal was signed, spot power sold near £35, and the plant's cost estimate later rose from £18bn to up to £35bn.", "kicker": "Apply cost per megawatt-hour to a nuclear megaproject.", "fullText": "Hinkley Point C is a 3.2 GW nuclear plant in England, two 1.6 GW reactors. Its contract for difference guarantees £92.50 per megawatt-hour in 2012 prices, indexed to inflation, for 35 years. In 2016, spot prices were around £35 per megawatt-hour, so the gap would be paid as a top-up.\n\nIn January 2024, EDF said the plant could cost £31bn to £35bn in 2015 prices, against £18bn when it was approved in 2016, and start between 2029 and 2031.", "sources": [{"url": "https://www.carbonbrief.org/the-hinkley-c-new-nuclear-plant", "label": "Carbon Brief, Q&A on Hinkley Point C"}, {"url": "https://uk.finance.yahoo.com/news/hinkley-point-c-could-delayed-185046161.html", "label": "Yahoo Finance, Hinkley Point C could be delayed to 2031"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What does a fixed £92.50 per MWh for 35 years give the plant?", "options": ["A known price for every MWh it makes", "Free construction paid by taxpayers", "Payment whether or not it ever runs"], "correctIndex": 0, "explanation": "A contract for difference tops up market prices to the strike price for each MWh the plant generates."}, "numbers": {"kind": "numberSense", "prompt": "For how many years does the Hinkley Point C price guarantee run?", "min": 0, "max": 60, "value": 35, "unit": "years", "explanation": "35 years, longer than most power contracts."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An analyst interview asks how to compare Hinkley Point C with a solar farm.", "prompt": "Which approach is sound?", "options": ["Compare the size of each site in acres", "Compare which one was approved first", "Compare cost per MWh, then add firming needs"], "correctIndex": 2, "consequences": ["Land area says little about cost.", "Approval dates do not compare cost.", "Per-MWh cost is fair; firming fills LCOE's gap."], "explanation": "Cost per MWh makes plants comparable, but firming costs sit outside LCOE."}, "proReasoning": "Strong analysts start with cost per MWh and then say what it misses. That balance is the skill.", "commonMistake": "Comparing a nuclear plant and a solar farm on capacity alone.", "mentalModel": "Per MWh first, then the blind spots."}, "invest": {"call": {"kind": "theCall", "situation": "You could invest in Hinkley Point C. Its cost estimate nearly doubled.", "prompt": "What does a fixed strike price mean for your return?", "options": ["Overruns cut returns, since revenue is fixed", "Overruns raise the strike price for you", "Overruns do not matter under the contract"], "correctIndex": 0, "consequences": ["Higher cost with a fixed price squeezes returns.", "The strike price is set, not adjusted for overruns.", "Cost always matters to the owner."], "explanation": "With revenue per MWh fixed, cost overruns fall on the owners."}, "proReasoning": "Investors in fixed-price projects watch the cost line. The price is locked; the build cost is not.", "commonMistake": "Treating a guaranteed price as a guaranteed return.", "mentalModel": "Fixed price, variable cost, real risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Megaprojects like Hinkley Point C run years late and over budget.", "prompt": "Where could your startup help?", "options": ["Designing a new kind of reactor", "Tracking schedule and cost risk early", "Lowering the strike price in contracts"], "correctIndex": 1, "consequences": ["A reactor design takes decades.", "Delays drive overruns, so early warning pays.", "Contract prices are set by governments."], "explanation": "Cost rose from £18bn to up to £35bn with years of delay. Better project control helps."}, "proReasoning": "Founders target the costliest problem they can actually solve. Megaproject delays are expensive and common.", "commonMistake": "Picking a problem that takes decades to address.", "mentalModel": "Solve the delay, save the budget."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why would Britain promise far more than the market price for nuclear power?", "prompt": "What's the main reason?", "options": ["Because nuclear power is always cheapest", "Because wind and solar were banned", "To get steady low-carbon power for decades"], "correctIndex": 2, "consequences": ["Its strike price was well above market.", "Britain also built wind and solar.", "Nuclear runs steadily, which LCOE alone misses."], "explanation": "The cheapest megawatt-hour is not always the most valuable; steady output has value."}, "proReasoning": "Price per MWh is only part of the story. Steady, low-carbon supply is worth paying for.", "commonMistake": "Assuming governments always buy the cheapest power.", "mentalModel": "Cheapest is not always most valuable."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7fc9bbbba126$ml$]::text[]),
($ml$bdeadc04-d14a-538b-bee0-1cff851ffe18$ml$::uuid, $ml$cleanenergy$ml$, 7, 2, $ml${"id": "cleanenergy-d7-c2", "title": "Cheap power, but which kind?", "lessonTitle": "Comparing power plants fairly", "slot": 2, "type": "connect", "brief": {"headline": "Lazard put new US utility-scale solar at $38 to $78 per MWh in 2025 without subsidies. Gas still made about 41% of US power, and wind's range rose to $37 to $86.", "kicker": "Connect day 4 and day 7: the cheapest new plant is not the biggest source.", "fullText": "On day 4 you saw the 2025 mix: gas about 41%, nuclear 18%, coal 17%, wind 11% and solar 7%.\n\nOn day 7, Lazard's 2025 levelized costs showed new solar at $38 to $78 per megawatt-hour unsubsidized, or $20 to $45 with tax credits. Onshore wind rose to $37 to $86 from $27 to $73 a year earlier. LCOE leaves out firming, the cost of backup when the sun sets or the wind drops.", "sources": [{"url": "https://www.eia.gov/energyexplained/electricity/electricity-in-the-us.php", "label": "EIA, electricity in the US"}, {"url": "https://www.pv-tech.org/us-utility-scale-solar-pv-lcoe-tightens-to-us38-78-mwh-in-2025-lazard/", "label": "PV Tech, Lazard 2025 LCOE for US solar"}]}, "evidence": {"kind": "faceOff", "prompt": "Which had the lower bottom of its 2025 unsubsidized LCOE range?", "left": {"name": "Onshore wind", "note": "$37 to $86 per MWh"}, "right": {"name": "Utility solar", "note": "$38 to $78 per MWh"}, "correctIndex": 0, "explanation": "Wind started at $37, a dollar below solar's $38, though its top end was higher."}, "numbers": {"kind": "numberSense", "prompt": "With tax credits, what was the low end of Lazard's 2025 US solar range, in $ per MWh?", "min": 0, "max": 100, "value": 20, "unit": "$", "explanation": "$20 per MWh, with the subsidized range running $20 to $45."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A colleague says solar is cheapest, so it should already make most US power.", "prompt": "How do you respond?", "options": ["Cheap new plants replace the old fleet slowly", "Solar is actually the most costly option", "Gas will vanish from the grid next year"], "correctIndex": 0, "consequences": ["Existing plants keep running for years.", "Solar is among the cheapest new builds.", "Gas still made about 41% in 2025."], "explanation": "LCOE ranks new plants. The mix reflects decades of existing ones, and firming costs matter too."}, "proReasoning": "Analysts separate cost of new builds from the shape of today's fleet. Both matter.", "commonMistake": "Thinking the cheapest new option instantly takes over.", "mentalModel": "New-build cost is not market share."}, "invest": {"call": {"kind": "theCall", "situation": "Wind's cost range rose in 2025 while solar's held.", "prompt": "What should you check on a wind project?", "options": ["Whether gas plants nearby stopped running", "Whether rising costs still fit its contract", "Whether solar panels got more costly this year"], "correctIndex": 1, "consequences": ["Gas did not stop running.", "Costs rose; contracts may not have.", "This is about the wind project."], "explanation": "Onshore wind's range moved up to $37 to $86. Rising costs squeeze fixed-price deals."}, "proReasoning": "Investors know costs do not always fall. Wind got pricier in 2025.", "commonMistake": "Assuming every renewable cost only goes down.", "mentalModel": "Costs can rise; check the contract."}, "build_startup": {"call": {"kind": "theCall", "situation": "Solar is cheap per MWh, but LCOE leaves out backup.", "prompt": "What gap could you build for?", "options": ["Cheaper solar panels than China makes", "Bigger solar farms at noon", "Storage or demand that fills sunset hours"], "correctIndex": 2, "consequences": ["Competing on panels is a price war.", "More noon power deepens the gap.", "Firming is the gap LCOE skips."], "explanation": "Cheap solar needs backup. Storage and flexible demand cover what LCOE leaves out."}, "proReasoning": "Founders build where the metric is blind. LCOE misses firming, so firming is the opportunity.", "commonMistake": "Adding more of what is already cheap.", "mentalModel": "Build where the metric is blind."}, "curiosity": {"call": {"kind": "theCall", "situation": "If new solar costs under $40 per MWh, why are bills not falling?", "prompt": "What's one reason?", "options": ["Bills cover the grid and the whole fleet", "Solar farms charge each home directly for power", "LCOE already includes delivery to every home"], "correctIndex": 0, "consequences": ["Bills include wires and existing plants.", "Homes buy from utilities, not farms.", "LCOE covers only the plant."], "explanation": "LCOE is a plant's own cost. Bills pay for the whole system, including the grid."}, "proReasoning": "A cheap plant does not make a cheap bill. The bill pays for everything between the plant and you.", "commonMistake": "Comparing a plant's cost to a household price.", "mentalModel": "Plant cost is not the bill."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e75458f515f2$ml$]::text[]),
($ml$d9cb63bf-7f19-5a1b-a0be-f9e0fe968645$ml$::uuid, $ml$cleanenergy$ml$, 7, 3, $ml${"id": "cleanenergy-d7-c3", "title": "Two offers for one data center", "lessonTitle": "Comparing power plants fairly", "slot": 3, "type": "decide", "brief": {"headline": "You buy power for a data center that runs day and night. One offer is solar at a low price per MWh; the other is firm power at a higher price. Lazard put new solar at $38 to $78 per MWh, before firming.", "kicker": "Decide: is the cheapest megawatt-hour the best deal for you?", "fullText": "Your data center uses power around the clock. A solar developer offers energy near the low end of Lazard's 2025 range of $38 to $78 per megawatt-hour. Another supplier offers firm power that runs at night too, at a higher price.\n\nLCOE divides a plant's lifetime costs by its lifetime output, but it does not include backup when the sun sets. Those firming costs have been rising. In power markets, the cheapest megawatt-hour is not always the most valuable one.", "sources": [{"url": "https://www.pv-tech.org/us-utility-scale-solar-pv-lcoe-tightens-to-us38-78-mwh-in-2025-lazard/", "label": "PV Tech, Lazard 2025 LCOE for US solar"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["LCOE spreads lifetime costs over lifetime output.", "LCOE includes the cost of backup at night.", "Lazard's 2025 solar range was $38 to $78."], "fakeIndex": 1, "explanation": "LCOE leaves out firming, the cost of backup when the sun sets or wind drops."}, "numbers": {"kind": "numberSense", "prompt": "What was the top of Lazard's 2025 unsubsidized US solar range, in $ per MWh?", "min": 0, "max": 200, "value": 78, "unit": "$", "explanation": "$78 per MWh, with the range starting at $38."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks which offer you recommend for the data center.", "prompt": "How do you frame it?", "options": ["Pick firm power, since price never matters", "Compare costs once night supply is covered", "Pick solar, since its LCOE is lower"], "correctIndex": 1, "consequences": ["Price always matters in procurement.", "A fair comparison adds what solar needs at night.", "LCOE alone ignores your night use."], "explanation": "Compare offers on the same service: power when you need it, including at night."}, "proReasoning": "Buyers compare like with like. Solar plus backup versus firm power is the honest comparison.", "commonMistake": "Comparing a daytime product with a 24-hour need.", "mentalModel": "Compare the same service."}, "invest": {"call": {"kind": "theCall", "situation": "You can fund a solar farm or a firm clean power plant selling to data centers.", "prompt": "What could make the pricier plant worth more?", "options": ["It has a larger site footprint on the map", "It produces its power only around noon", "Its power is available when buyers need it"], "correctIndex": 2, "consequences": ["Footprint does not set value.", "Noon power is the cheap kind.", "Timing of delivery adds value."], "explanation": "Value depends on when power is delivered, not just its cost per MWh."}, "proReasoning": "Investors price the hour, not just the megawatt-hour. Delivery timing drives value.", "commonMistake": "Ranking projects by LCOE alone.", "mentalModel": "Value follows the hour."}, "build_startup": {"call": {"kind": "theCall", "situation": "Data centers want cheap solar but run all night.", "prompt": "What could your startup sell them?", "options": ["Storage that shifts solar into the night", "More panels on the data center roof", "Software to measure noon output"], "correctIndex": 0, "consequences": ["That turns cheap solar into night power.", "Roof panels add little at night.", "Measuring noon does not fill night."], "explanation": "Cheap solar needs firming. Storage closes the gap between supply and night use."}, "proReasoning": "Founders bridge the cheap resource and the real need. Shifting solar into the night is that bridge.", "commonMistake": "Selling more of the cheap resource without fixing timing.", "mentalModel": "Shift the cheap power to the need."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why would a company pay more per MWh than the cheapest offer?", "prompt": "What's the best reason?", "options": ["Cheap offers are always fake", "It needs power at night too", "It wants to waste money"], "correctIndex": 1, "consequences": ["Cheap solar offers are real.", "Round-the-clock needs change the math.", "Companies do not pay more for nothing."], "explanation": "The cheapest megawatt-hour is not always the most valuable one."}, "proReasoning": "Price depends on what you need. Night power is worth more to a 24-hour user.", "commonMistake": "Assuming the lowest price always wins.", "mentalModel": "Need sets value."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:da95e5eee63b$ml$]::text[]),
($ml$7c359c2c-339f-5839-8501-1c3db7e7edf5$ml$::uuid, $ml$cleanenergy$ml$, 8, 1, $ml${"id": "cleanenergy-d8-c1", "title": "A German factory goes quiet", "lessonTitle": "Solar panels at record lows", "slot": 1, "type": "apply", "brief": {"headline": "In March 2024, Meyer Burger stopped making modules at its factory in Freiberg, Germany. Cheap Chinese panels were flooding Europe, and about 500 jobs were affected.", "kicker": "Apply the price crash to a maker outside China.", "fullText": "Meyer Burger had asked Germany for a \"resilience bonus\" for locally made solar components. The government declined, and production stopped in mid-March 2024. About 400 workers got termination notices for the end of April, and around 100 more were in talks to move to other sites.\n\nShareholders backed a rights issue of about CHF 200 million to expand the company's US production. Meanwhile, Chinese module prices had fallen 47.83% in 2023 to a record low.", "sources": [{"url": "https://taiyangnews.info/amp/story/markets/meyer-burger-finally-closing-down-freiberg-module-facility", "label": "TaiyangNews, Meyer Burger closing Freiberg module facility"}, {"url": "https://www.opis.com/blog/china-solar-value-chain-price/", "label": "OPIS, China solar value chain prices"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Production in Freiberg stopped in March 2024.", "Germany granted Meyer Burger a resilience bonus.", "The company planned to expand in the US."], "fakeIndex": 1, "explanation": "The government declined the bonus, and the factory stopped making modules."}, "numbers": {"kind": "numberSense", "prompt": "About how many jobs did the Freiberg closure affect?", "min": 0, "max": 2000, "value": 500, "explanation": "About 500: some 400 termination notices plus about 100 in transfer talks."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are offered a job at a European solar factory in 2024.", "prompt": "What should you ask first?", "options": ["How it competes with record-low Chinese prices", "How sunny the factory's location is all year", "How many panels it shipped back in 2010"], "correctIndex": 0, "consequences": ["Price pressure decides whether factories survive.", "Factories do not need sunshine.", "Old volumes say little about today."], "explanation": "Overcapacity in China pushed prices below many makers' costs. Survival depends on how a factory competes."}, "proReasoning": "Candidates who ask about cost position show they understand the market. Makers outside China face tough math.", "commonMistake": "Assuming demand for solar means every factory is safe.", "mentalModel": "Ask how they beat the price."}, "invest": {"call": {"kind": "theCall", "situation": "A European module maker seeks funding as Chinese prices hit record lows.", "prompt": "What is the main risk?", "options": ["Too little sunshine in Europe", "Selling below cost against Chinese supply", "Running out of buyers for solar power"], "correctIndex": 1, "consequences": ["Sunshine does not drive factory margins.", "The price war squeezed makers everywhere.", "Developers kept buying panels."], "explanation": "Overcapacity crushed module margins, so makers outside China struggled to compete."}, "proReasoning": "Investors separate demand for solar from profits in making it. Demand grew while margins collapsed.", "commonMistake": "Treating a booming market as a profitable one.", "mentalModel": "Booming demand, crushed margins."}, "build_startup": {"call": {"kind": "theCall", "situation": "Panels are cheaper than ever, and factories are closing.", "prompt": "Where is the opportunity for a startup?", "options": ["A new panel factory in Germany to rival China", "Raising panel prices for the buyers you serve", "Products that use cheap panels in new ways"], "correctIndex": 2, "consequences": ["Factories there just closed.", "Buyers have plenty of cheap supply.", "Cheap hardware makes new uses viable."], "explanation": "Overcapacity is a gift to buyers. Build on cheap panels rather than competing to make them."}, "proReasoning": "Founders ride falling hardware costs instead of fighting them. Cheap panels enable new products.", "commonMistake": "Entering a price war you cannot win.", "mentalModel": "Build on cheap, do not make cheap."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why would a solar factory close if solar is growing?", "prompt": "What's the best answer?", "options": ["Prices fell below what it cost to make panels", "Nobody wanted to buy solar panels anymore", "The factory ran out of sunlight to use"], "correctIndex": 0, "consequences": ["Overcapacity pushed prices under costs.", "Demand kept growing.", "Factories make panels; they do not use sun."], "explanation": "Too much capacity drove prices so low that some makers could not cover costs."}, "proReasoning": "Growth in use and profits in making can move in opposite directions.", "commonMistake": "Assuming a growing market protects every company in it.", "mentalModel": "More demand, lower prices, fewer makers."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:51763ba1fb40$ml$]::text[]),
($ml$1f789cd5-78f5-57ee-ab08-94e10e853846$ml$::uuid, $ml$cleanenergy$ml$, 8, 2, $ml${"id": "cleanenergy-d8-c2", "title": "Cheap panels, cheaper power", "lessonTitle": "Solar panels at record lows", "slot": 2, "type": "connect", "brief": {"headline": "Chinese module prices fell 47.83% in 2023 to a record $0.120 per watt, and polysilicon fell 56%. Lower equipment costs feed straight into the cost of a solar megawatt-hour.", "kicker": "Connect day 7 and day 8: module prices flow into LCOE.", "fullText": "On day 7 you met LCOE: a plant's lifetime costs divided by its lifetime output. Building the plant is a big part of those costs, and modules are a big part of the build.\n\nOn day 8, Chinese factories had expanded fast, with module output up 69% in 2023. Prices across the chain fell near or below cash costs. Developers got cheaper equipment; manufacturers absorbed the losses.", "sources": [{"url": "https://www.opis.com/blog/china-solar-value-chain-price/", "label": "OPIS, China solar value chain prices"}, {"url": "https://www.pv-tech.org/us-utility-scale-solar-pv-lcoe-tightens-to-us38-78-mwh-in-2025-lazard/", "label": "PV Tech, Lazard 2025 LCOE for US solar"}]}, "evidence": {"kind": "buildChain", "prompt": "Follow the price crash from factory to power.", "steps": ["Chinese factories add capacity fast", "Module supply outruns demand", "Module prices fall to record lows", "Solar farms cost less to build", "Solar LCOE moves lower"], "explanation": "Overcapacity cut module prices, which lowered build costs and therefore the cost per MWh."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did Chinese polysilicon prices fall in 2023?", "min": 0, "max": 90, "value": 56, "unit": "%", "explanation": "56%, while module prices fell 47.83%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked why solar LCOE stays low.", "prompt": "What is a strong answer?", "options": ["Governments set the LCOE of solar", "Module prices crashed from overcapacity", "Solar plants need no maintenance at all"], "correctIndex": 1, "consequences": ["LCOE is calculated, not set.", "Cheaper modules lower build cost.", "Operating costs are part of LCOE."], "explanation": "Overcapacity pushed module prices to records, cutting the build cost in LCOE."}, "proReasoning": "Linking the supply chain to LCOE shows you see the whole system.", "commonMistake": "Explaining cost trends without naming the equipment market.", "mentalModel": "Chain prices drive plant costs."}, "invest": {"call": {"kind": "theCall", "situation": "You can invest in a solar developer or a module maker in 2024.", "prompt": "Who benefits more from the price crash?", "options": ["The maker selling modules near cost", "Both gain by exactly the same amount", "The developer buying cheap modules"], "correctIndex": 2, "consequences": ["Makers absorbed the losses.", "One side's cost is the other's price.", "Cheaper inputs lift developer margins."], "explanation": "Developers got cheaper equipment while makers sold near or below cost."}, "proReasoning": "Investors pick the side of the trade that gains. A price crash helps the buyer.", "commonMistake": "Betting on makers because solar is growing.", "mentalModel": "A price crash helps the buyer."}, "build_startup": {"call": {"kind": "theCall", "situation": "Modules now cost about 12 cents a watt.", "prompt": "Which idea benefits most?", "options": ["Products that need lots of panels", "A premium hand-made panel brand", "Repairing very old panels"], "correctIndex": 0, "consequences": ["Cheap panels make panel-heavy ideas viable.", "Premium pricing fights the trend.", "New panels are cheaper than repairs."], "explanation": "Cheap modules make uses that need many panels newly affordable."}, "proReasoning": "Founders ask what becomes possible when an input gets cheap. That is often the opening.", "commonMistake": "Ignoring a big drop in your key input cost.", "mentalModel": "Cheap inputs open new products."}, "curiosity": {"call": {"kind": "theCall", "situation": "How did solar power get so cheap so fast?", "prompt": "What's one big reason?", "options": ["Panels became much smaller and lighter", "Factories built more panels than needed", "The sun got brighter in recent years"], "correctIndex": 1, "consequences": ["Size is not the reason.", "Overcapacity pushed prices down.", "The sun did not change."], "explanation": "China produced over 499 GW of modules in 2023, far more than the world installed."}, "proReasoning": "Prices often fall when supply outruns demand. Solar panels are a clear example.", "commonMistake": "Thinking cost drops come only from inventions.", "mentalModel": "Too much supply, lower price."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e067ed249751$ml$]::text[]),
($ml$a55f23e5-a8f4-5bb4-a428-77a26bd03fa4$ml$::uuid, $ml$cleanenergy$ml$, 8, 3, $ml${"id": "cleanenergy-d8-c3", "title": "Buy panels now or later", "lessonTitle": "Solar panels at record lows", "slot": 3, "type": "decide", "brief": {"headline": "You buy modules for a solar developer in late 2023. Prices fell 47.83% that year to $0.120 per watt, and makers are selling at or below cost.", "kicker": "Decide: lock in modules now, or wait for even lower prices?", "fullText": "Your company plans several solar farms over two years. Chinese module output rose 69% in 2023, and prices across the chain sat barely above, or below, cash costs. Smaller makers were already selling below cost.\n\nPrices this low cannot fall forever if makers are losing money. Some may cut output or close. In solar, overcapacity is a gift to buyers and a crisis for makers.", "sources": [{"url": "https://www.opis.com/blog/china-solar-value-chain-price/", "label": "OPIS, China solar value chain prices"}]}, "evidence": {"kind": "faceOff", "prompt": "Who gained most from record-low module prices in 2023?", "left": {"name": "Solar developers", "note": "Buy modules for projects"}, "right": {"name": "Module makers", "note": "Sell modules near cost"}, "correctIndex": 0, "explanation": "Developers got cheaper equipment while makers absorbed the losses."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did Chinese module output rise in 2023?", "min": 0, "max": 150, "value": 69, "unit": "%", "explanation": "69%, which helped push prices to records."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks whether to buy all two years of modules now.", "prompt": "What do you recommend?", "options": ["Wait, since prices will keep falling forever", "Buy nothing at all until the makers recover", "Lock in a good share now, keep some flexible"], "correctIndex": 2, "consequences": ["Below-cost prices cannot last forever.", "You risk paying more later.", "You capture low prices without betting it all."], "explanation": "Prices near cost are a buying chance, but timing every purchase is risky. Split the bet."}, "proReasoning": "Procurement leads hedge timing. They buy a solid share at good prices and keep options open.", "commonMistake": "Assuming a falling price will keep falling.", "mentalModel": "Lock in some, keep some open."}, "invest": {"call": {"kind": "theCall", "situation": "Module makers are selling below cost.", "prompt": "What do you watch for next?", "options": ["Factory cuts and consolidation", "A sudden end to solar demand", "Makers raising prices with no cuts"], "correctIndex": 0, "consequences": ["Losses force output cuts and mergers.", "Demand kept growing.", "Without cuts, pricing power is weak."], "explanation": "Overcapacity crushed margins; the usual next step is cuts and consolidation."}, "proReasoning": "Investors watch for supply discipline after a price war. Cuts usually come before recovery.", "commonMistake": "Expecting prices to bounce without any capacity cuts.", "mentalModel": "Price wars end with cuts."}, "build_startup": {"call": {"kind": "theCall", "situation": "Developers struggle to time module purchases in a falling market.", "prompt": "What could your startup offer?", "options": ["Insurance against sunny weather", "Price data and buying timing tools", "A new module factory"], "correctIndex": 1, "consequences": ["Sun is the product, not the risk.", "Better timing saves buyers real money.", "Making modules means joining the price war."], "explanation": "Buying modules well is a key job when prices swing this much."}, "proReasoning": "Founders help buyers navigate volatile prices. Data beats guessing in a swinging market.", "commonMistake": "Joining the losing side of a price war.", "mentalModel": "Sell clarity in a swinging market."}, "curiosity": {"call": {"kind": "theCall", "situation": "Can solar panel prices keep falling if makers lose money?", "prompt": "What's most likely?", "options": ["Prices keep falling until they reach zero", "Makers keep on losing money forever", "Some makers cut output, steadying prices"], "correctIndex": 2, "consequences": ["Nobody sells below cost forever.", "Companies cannot lose money indefinitely.", "Losses push supply down over time."], "explanation": "Selling below cost cannot last; supply usually shrinks until prices steady."}, "proReasoning": "Markets correct when sellers lose money. Supply shrinks, and prices find a floor.", "commonMistake": "Extending a price trend forever.", "mentalModel": "Losses shrink supply."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:330e1022d021$ml$]::text[]),
($ml$1905168d-c6ba-5014-b192-ccff246dccd2$ml$::uuid, $ml$cleanenergy$ml$, 9, 1, $ml${"id": "cleanenergy-d9-c1", "title": "An American polysilicon plant shuts", "lessonTitle": "China's grip on solar", "slot": 1, "type": "apply", "brief": {"headline": "In late 2024, REC Silicon shut its polysilicon plant in Moses Lake, Washington, after Qcells cancelled a 10-year supply deal. The plant was meant to feed a US-made solar supply chain.", "kicker": "Apply China's grip to a US attempt to break it.", "fullText": "REC and Hanwha signed a 10-year deal in 2023 for polysilicon made at Moses Lake for Qcells' Georgia factories. Qcells' tests of REC's samples failed, and it cancelled. REC cut 224 jobs and also stopped polysilicon output at its Butte, Montana site.\n\nQcells said it would source polysilicon for its Cartersville, Georgia plant from OCI's factory in Malaysia. Outside China, building the first step of the chain proved hard. China holds more than 80% of capacity at every stage.", "sources": [{"url": "https://www.manufacturingdive.com/news/rec-silicon-closing-moses-lake-washington-polysilicon-plant-qcells/737640/", "label": "Manufacturing Dive, REC Silicon closes Moses Lake"}, {"url": "https://iea.org/reports/solar-pv-global-supply-chains/executive-summary", "label": "IEA, Solar PV global supply chains"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why did Qcells cancel the Moses Lake supply deal?", "options": ["It stopped making solar panels entirely", "Its tests of REC polysilicon samples failed", "Its Georgia factory had closed for good"], "correctIndex": 1, "explanation": "Qcells' ingot tests of REC's samples failed, and it chose not to wait for a fix."}, "numbers": {"kind": "numberSense", "prompt": "How many jobs did REC Silicon cut at Moses Lake?", "min": 0, "max": 1000, "value": 224, "explanation": "224 jobs, per Washington state records."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a US solar maker. They ask about supply chain risk.", "prompt": "What example do you give?", "options": ["Polysilicon is no longer needed", "Moses Lake shows how hard US poly is", "US poly plants run at full output"], "correctIndex": 1, "consequences": ["Most cells still use polysilicon.", "A real case shows you know the bottleneck.", "The plant shut down."], "explanation": "Building polysilicon outside China failed here, which shows how concentrated the chain is."}, "proReasoning": "Using a concrete case beats a generic answer. Moses Lake shows where the chain breaks.", "commonMistake": "Assuming the US can quickly build every step at home.", "mentalModel": "Name the weak link with a case."}, "invest": {"call": {"kind": "theCall", "situation": "A new non-China polysilicon plant seeks funding.", "prompt": "What do you check first?", "options": ["How close it is to a beach", "Whether China makes polysilicon too", "Whether its product meets buyer specs"], "correctIndex": 2, "consequences": ["Location matters, but not like that.", "Everyone knows China dominates.", "Failed specs sank the Qcells deal."], "explanation": "A supply deal is only as good as the product. Failed tests ended REC's contract."}, "proReasoning": "Investors test the product before the plan. A contract means little if samples fail.", "commonMistake": "Trusting a signed contract over product proof.", "mentalModel": "Proof of product beats the contract."}, "build_startup": {"call": {"kind": "theCall", "situation": "US solar makers need to prove where polysilicon comes from.", "prompt": "What could your startup build?", "options": ["Tools that trace materials through the chain", "A cheaper home solar app for homeowners", "More coal power for the solar factories"], "correctIndex": 0, "consequences": ["Buyers must show origin; tracing helps.", "That misses the supply chain need.", "That does not address origin."], "explanation": "With most polysilicon from China, buyers need proof of where materials came from."}, "proReasoning": "Founders sell proof when rules demand it. Traceability turns a risk into a product.", "commonMistake": "Building hardware when buyers need records.", "mentalModel": "Sell proof of origin."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why would a US solar maker buy polysilicon from Malaysia?", "prompt": "What's the main reason?", "options": ["US law forbids making it at home", "Few plants outside China make it", "Malaysia has the sunniest weather"], "correctIndex": 1, "consequences": ["No law forbids it.", "Supply outside China is scarce.", "Weather does not make polysilicon."], "explanation": "With the US plant shut, Qcells turned to OCI in Malaysia, one of few non-China sources."}, "proReasoning": "Concentration leaves few options. When one supplier fails, the alternatives are far away.", "commonMistake": "Assuming supplies can be found anywhere.", "mentalModel": "Few makers, few options."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:fba26e72032f$ml$]::text[]),
($ml$2c9c875a-4b68-5621-a69c-de498304de73$ml$::uuid, $ml$cleanenergy$ml$, 9, 2, $ml${"id": "cleanenergy-d9-c2", "title": "From overcapacity to control", "lessonTitle": "China's grip on solar", "slot": 2, "type": "connect", "brief": {"headline": "China holds more than 80% of global capacity at every stage of solar manufacturing. Based on capacity under construction, the IEA expected its share of polysilicon, ingots and wafers to reach almost 95%.", "kicker": "Connect day 8 and day 9: the same capacity that crashed prices concentrates control.", "fullText": "On day 8 you saw Chinese module prices fall 47.83% in 2023 as factories expanded far beyond demand.\n\nOn day 9, the IEA shows the other side. China leads every step: polysilicon, ingots, wafers, cells and modules. It invested over $50 billion in solar supply capacity since 2011, about ten times Europe's investment. Cheap prices and concentrated control come from the same buildout.", "sources": [{"url": "https://iea.org/reports/solar-pv-global-supply-chains/executive-summary", "label": "IEA, Solar PV global supply chains"}, {"url": "https://www.opis.com/blog/china-solar-value-chain-price/", "label": "OPIS, China solar value chain prices"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the steps of making a solar panel in order.", "steps": ["Purify silicon into polysilicon", "Cast polysilicon into ingots", "Slice ingots into wafers", "Turn wafers into cells", "Assemble cells into modules"], "explanation": "Polysilicon, ingots, wafers, cells, modules. China leads every step."}, "numbers": {"kind": "numberSense", "prompt": "What share of polysilicon, ingots and wafers did the IEA expect China to reach?", "min": 0, "max": 100, "value": 95, "unit": "%", "explanation": "Almost 95%, based on capacity under construction."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks how China's solar dominance and low prices relate.", "prompt": "What is the sharpest answer?", "options": ["They are unrelated trends", "Low prices reduced China's share", "The same buildout drove both"], "correctIndex": 2, "consequences": ["They share one cause.", "China's share kept rising.", "Massive capacity crashed prices and won share."], "explanation": "Over $50 billion of capacity created both overcapacity and concentration."}, "proReasoning": "Connecting price and power shows strategic thinking. One buildout, two effects.", "commonMistake": "Discussing prices and supply chain risk as separate topics.", "mentalModel": "One buildout, two effects."}, "invest": {"call": {"kind": "theCall", "situation": "A rival supplier outside China says low prices are temporary.", "prompt": "What makes its plan hard?", "options": ["China's scale lets it keep prices low", "Demand for solar is shrinking every year", "Panels are getting more costly to make"], "correctIndex": 0, "consequences": ["Huge capacity keeps pressure on prices.", "Demand kept growing.", "Prices hit record lows."], "explanation": "With over 80% of every stage, China's capacity keeps prices under pressure for rivals."}, "proReasoning": "Investors test rivals against the leader's cost position. Scale is a lasting advantage.", "commonMistake": "Betting that a dominant producer's prices will soon rise.", "mentalModel": "Scale keeps prices low."}, "build_startup": {"call": {"kind": "theCall", "situation": "Every step of the solar chain runs through China.", "prompt": "Which startup idea fits best?", "options": ["Banning the imports by yourself", "Mapping and diversifying supply chains", "Competing with China on polysilicon cost"], "correctIndex": 1, "consequences": ["Startups cannot set trade policy.", "Buyers need help reducing concentration.", "China leads on cost at every step."], "explanation": "Solar firms need people and tools to map and diversify supply chains."}, "proReasoning": "Founders help buyers manage concentration rather than fight it head on.", "commonMistake": "Taking on the dominant producer on cost.", "mentalModel": "Help buyers manage concentration."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why does one country make most solar panels?", "prompt": "What's the main reason?", "options": ["Only China has silicon to mine", "Other countries banned solar", "It invested far more in factories"], "correctIndex": 2, "consequences": ["Silicon exists in many countries.", "No such bans exist.", "Over $50 billion since 2011, ten times Europe."], "explanation": "China invested over $50 billion in solar supply capacity since 2011."}, "proReasoning": "Industrial leadership usually follows investment. Here the gap was tenfold.", "commonMistake": "Assuming dominance comes from natural resources alone.", "mentalModel": "Investment builds dominance."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:23860f0ec2c0$ml$]::text[]),
($ml$af4fce43-514c-5d59-9806-a68d32140aca$ml$::uuid, $ml$cleanenergy$ml$, 9, 3, $ml${"id": "cleanenergy-d9-c3", "title": "A utility wants a cleaner supply chain", "lessonTitle": "China's grip on solar", "slot": 3, "type": "decide", "brief": {"headline": "Your utility wants solar panels with less supply chain risk. China holds over 80% of every manufacturing stage, and Xinjiang alone makes about 40% of the world's polysilicon.", "kicker": "Decide: what is a realistic sourcing plan?", "fullText": "You run procurement for a utility building solar farms. Your board worries about depending on one country.\n\nThe IEA found China leads every step from polysilicon to modules, with over 80% of capacity at each stage. One region, Xinjiang, makes about 40% of global polysilicon. China invested over $50 billion in solar supply capacity since 2011, about ten times Europe. When one country dominates every step, any disruption there affects solar worldwide.", "sources": [{"url": "https://iea.org/reports/solar-pv-global-supply-chains/executive-summary", "label": "IEA, Solar PV global supply chains"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan cuts risk while keeping costs workable?", "left": {"name": "Diversify and trace materials", "note": "Where the chain allows it"}, "right": {"name": "Demand zero China content", "note": "Across every stage"}, "correctIndex": 0, "explanation": "With China above 80% at every stage, zero China content is rarely possible. Diversifying and tracing are practical."}, "numbers": {"kind": "numberSense", "prompt": "How many billion dollars has China invested in solar supply capacity since 2011?", "min": 0, "max": 200, "value": 50, "unit": "B", "explanation": "Over $50 billion, about ten times Europe's investment."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your board asks for a sourcing plan by Friday.", "prompt": "What do you propose?", "options": ["Diversify suppliers and trace origins", "Promise panels with no China content", "Stop buying panels until it changes"], "correctIndex": 0, "consequences": ["You cut risk where the chain allows.", "At over 80% per stage, that is unrealistic.", "You give up cheap power."], "explanation": "Diversifying and tracing materials are the practical steps."}, "proReasoning": "Procurement leads give boards realistic plans. Promising zero exposure sets you up to fail.", "commonMistake": "Overpromising on a chain you cannot fully control.", "mentalModel": "Reduce risk, do not promise zero."}, "invest": {"call": {"kind": "theCall", "situation": "New solar factories are opening outside China.", "prompt": "What decides if they survive?", "options": ["How much sunshine they get", "Whether their costs can compete", "Whether China notices them"], "correctIndex": 1, "consequences": ["Factories do not run on sun.", "Cost is the test against China's scale.", "Attention does not set survival."], "explanation": "Plants outside China hedge concentration, but their costs decide if they last."}, "proReasoning": "Investors back diversification only when the costs work. A hedge that loses money closes.", "commonMistake": "Funding factories on strategy alone.", "mentalModel": "Hedges must still pay."}, "build_startup": {"call": {"kind": "theCall", "situation": "Buyers must show where their polysilicon came from.", "prompt": "What product sells?", "options": ["A robot that cleans solar panels on farms", "A cheaper inverter for home solar systems", "Software that traces materials to origin"], "correctIndex": 2, "consequences": ["Useful, but not this need.", "Not about origin.", "Tracing is exactly what buyers must prove."], "explanation": "Tools that trace materials have demand when buyers must prove origin."}, "proReasoning": "Founders follow compliance needs. Proving origin is a must-have for many buyers.", "commonMistake": "Building a nice product that misses the urgent need.", "mentalModel": "Follow the compliance need."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why does one region matter so much for solar?", "prompt": "What's the answer?", "options": ["Xinjiang makes about 40% of polysilicon", "Xinjiang uses most of the world's panels", "Xinjiang owns all solar patents"], "correctIndex": 0, "consequences": ["A big share of one input in one region is a risk.", "It makes polysilicon; others use panels.", "Patents are not the issue."], "explanation": "About 40% of the world's polysilicon comes from Xinjiang, so disruption there spreads."}, "proReasoning": "Concentration in one place means one event can ripple worldwide.", "commonMistake": "Treating a global industry as spread out when it is not.", "mentalModel": "Concentration spreads risk."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:78d48ccc1334$ml$]::text[]),
($ml$6b674aaa-787b-5d87-99ff-f505d4980982$ml$::uuid, $ml$cleanenergy$ml$, 10, 1, $ml${"id": "cleanenergy-d10-c1", "title": "The mirror field that lost", "lessonTitle": "How often plants actually run", "slot": 1, "type": "apply", "brief": {"headline": "Ivanpah, a 386 MW solar thermal plant in the Mojave, began planning to close its units in 2026. In January 2025, PG&E, which bought about two-thirds of its output, ended its contracts.", "kicker": "Apply capacity versus energy to a plant that faded.", "fullText": "Ivanpah uses mirrors to focus sunlight and boil water, across three units on 3,500 acres. It had no thermal storage, so like photovoltaic panels it made power only in sunlight.\n\nIts owners and the US Department of Energy agreed with PG&E to terminate two long-term purchase agreements. Ivanpah planned to begin closing units in early 2026, pending approvals. Photovoltaic solar had overtaken it with much lower building and operating costs.", "sources": [{"url": "https://www.nsenergybusiness.com/?p=361111", "label": "NS Energy, Ivanpah solar plant to close"}, {"url": "https://eia.gov/electricity/annual/html/epa_04_08_b.html", "label": "EIA, capacity factors for non-fossil generators"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Ivanpah has 386 MW across three units.", "Ivanpah stored heat to run all night.", "PG&E bought about two-thirds of its output."], "fakeIndex": 1, "explanation": "Ivanpah had no thermal storage, so it ran only in sunlight."}, "numbers": {"kind": "numberSense", "prompt": "About what share of Ivanpah's output did PG&E buy?", "min": 0, "max": 100, "value": 67, "unit": "%", "explanation": "About two-thirds, which is why ending its contracts mattered so much."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked why Ivanpah lost to photovoltaic solar.", "prompt": "What is the strongest answer?", "options": ["Ivanpah ran all night and wasted power", "PV panels produce power after sunset", "PV made similar power at much lower cost"], "correctIndex": 2, "consequences": ["Ivanpah had no storage and ran by day.", "PV panels stop at sunset too.", "Both run in sunlight, and PV costs far less."], "explanation": "Without storage, Ivanpah made daytime power like PV, at higher cost."}, "proReasoning": "Compare plants on the energy they deliver and what it costs. Same hours, higher cost loses.", "commonMistake": "Judging a plant by its megawatts or its novelty.", "mentalModel": "Same hours, higher cost, lost."}, "invest": {"call": {"kind": "theCall", "situation": "You hold debt in a plant whose main buyer just ended its contract.", "prompt": "What happens to the plant's value?", "options": ["It falls, since most revenue is gone", "It rises, since output is now free", "Nothing, since megawatts still exist"], "correctIndex": 0, "consequences": ["About two-thirds of sales went away.", "Output without a buyer earns nothing.", "Capacity without sales has little value."], "explanation": "Revenue comes from energy sold. Losing the main buyer guts the plant's value."}, "proReasoning": "Investors value contracted energy, not installed capacity. A plant is worth its sales.", "commonMistake": "Counting megawatts as if they were revenue.", "mentalModel": "A plant is worth what it sells."}, "build_startup": {"call": {"kind": "theCall", "situation": "Ivanpah lacked storage, so it ran only in sunlight.", "prompt": "What idea raises the value of solar plants?", "options": ["Paint panels to absorb more heat", "Add storage to deliver power after sunset", "Build bigger mirror fields in deserts"], "correctIndex": 1, "consequences": ["Paint does not add night hours.", "Storage adds the hours solar lacks.", "Bigger fields still stop at sunset."], "explanation": "Tools that let solar produce more useful hours, like storage, add real value."}, "proReasoning": "Founders raise the useful hours of a plant. That is what buyers pay for.", "commonMistake": "Scaling up the part that already has the same limits.", "mentalModel": "Add hours, add value."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why would a giant solar plant close after about a decade?", "prompt": "What's the best answer?", "options": ["The desert stopped getting sunshine", "The mirrors all broke at once", "Cheaper solar panels did the same job"], "correctIndex": 2, "consequences": ["The Mojave is still sunny.", "It closed for economic reasons.", "PV beat it on cost."], "explanation": "Photovoltaic solar surpassed it with much lower capital and operating costs."}, "proReasoning": "Technologies can lose even when they work. Cost decides who stays.", "commonMistake": "Assuming plants close only when they break.", "mentalModel": "Working is not enough; cost decides."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:42c979eada12$ml$]::text[]),
($ml$59fb2f3a-f1ed-5307-9270-ef87d299133a$ml$::uuid, $ml$cleanenergy$ml$, 10, 2, $ml${"id": "cleanenergy-d10-c2", "title": "Why nuclear punches above its weight", "lessonTitle": "How often plants actually run", "slot": 2, "type": "connect", "brief": {"headline": "US nuclear ran at a 91.1% capacity factor in 2025 and solar at 24.0%. That gap helps explain why nuclear made about 18% of US power while solar made about 7%.", "kicker": "Connect day 4 and day 10: capacity factor turns megawatts into the mix.", "fullText": "On day 4 you saw the 2025 mix: nuclear about 18% of US power, solar about 7%, wind 11%.\n\nOn day 10, EIA's capacity factors show why megawatts mislead. Nuclear ran at 91.1% of its full potential, wind 33.8%, hydropower 34.4% and solar 24.0%. Solar is limited by night and clouds; nuclear runs almost nonstop. A megawatt of solar is not a megawatt of nuclear.", "sources": [{"url": "https://eia.gov/electricity/annual/html/epa_04_08_b.html", "label": "EIA, capacity factors for non-fossil generators"}, {"url": "https://www.eia.gov/energyexplained/electricity/electricity-in-the-us.php", "label": "EIA, electricity in the US"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why can nuclear make more energy than solar with less capacity?", "options": ["It is paid more for each megawatt-hour", "It runs at full power far more of the time", "Its plants are physically much larger"], "correctIndex": 1, "explanation": "Nuclear's 91.1% capacity factor is almost four times solar's 24.0%."}, "numbers": {"kind": "numberSense", "prompt": "What was the US nuclear capacity factor in 2025?", "min": 0, "max": 100, "value": 91, "unit": "%", "explanation": "91.1%, against 24.0% for solar and 33.8% for wind."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks why 1 GW of solar does not replace 1 GW of nuclear.", "prompt": "What do you say?", "options": ["Solar runs far fewer hours at full power", "Solar panels wear out within months", "Nuclear plants are cheaper to build"], "correctIndex": 0, "consequences": ["24% versus 91% is the key gap.", "Panels last for decades.", "Cost was not the question."], "explanation": "Capacity factor turns megawatts into energy. Solar makes about a quarter of nuclear's energy per megawatt."}, "proReasoning": "Analysts convert megawatts to megawatt-hours before comparing. It is a core skill.", "commonMistake": "Comparing plants by nameplate megawatts alone.", "mentalModel": "Convert capacity to energy first."}, "invest": {"call": {"kind": "theCall", "situation": "Two plants of equal megawatts are for sale: solar and nuclear.", "prompt": "Which likely produces more revenue from energy?", "options": ["They earn the same per megawatt", "Nuclear, which runs nearly nonstop", "Solar, since its fuel is free"], "correctIndex": 1, "consequences": ["Output differs by nearly four times.", "More hours means more energy sold.", "Free fuel does not add hours."], "explanation": "Revenue comes from energy produced, and nuclear produces far more per megawatt."}, "proReasoning": "Investors value output, not nameplate. Capacity factor tells you how much a plant really makes.", "commonMistake": "Valuing two plants equally because their megawatts match.", "mentalModel": "Value the output."}, "build_startup": {"call": {"kind": "theCall", "situation": "Solar runs at a 24% capacity factor.", "prompt": "What kind of product adds the most value?", "options": ["Bigger nameplate solar panels", "Solar plants that run only at noon", "Ways to raise useful solar hours"], "correctIndex": 2, "consequences": ["Nameplate alone does not add hours.", "Noon is when solar already runs.", "More hours means more energy and revenue."], "explanation": "Trackers or storage that help solar produce more hours add real value."}, "proReasoning": "Founders attack the low capacity factor. Each extra hour is extra energy to sell.", "commonMistake": "Chasing nameplate size over useful hours.", "mentalModel": "Raise the factor."}, "curiosity": {"call": {"kind": "theCall", "situation": "There are more solar megawatts being built than nuclear. Why does nuclear make more power?", "prompt": "What's the answer?", "options": ["Nuclear runs day and night all year", "Solar power is wasted at night", "Nuclear plants are kept secret"], "correctIndex": 0, "consequences": ["About 91% of full potential, year round.", "Solar simply does not run at night.", "Nothing secret about it."], "explanation": "Nuclear runs at about 91% of its potential; solar about 24%."}, "proReasoning": "Megawatts tell you size; capacity factor tells you how much energy you get.", "commonMistake": "Reading capacity headlines as energy headlines.", "mentalModel": "Size is not energy."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:31d1b340190b$ml$]::text[]),
($ml$b541952b-7b99-5011-b45e-11ac3c160bbe$ml$::uuid, $ml$cleanenergy$ml$, 10, 3, $ml${"id": "cleanenergy-d10-c3", "title": "Choosing between wind and solar", "lessonTitle": "How often plants actually run", "slot": 3, "type": "decide", "brief": {"headline": "You can build 100 MW of wind or 100 MW of solar on similar budgets. In 2025, US wind ran at a 33.8% capacity factor and solar at 24.0%.", "kicker": "Decide: which 100 MW gives you more energy to sell?", "fullText": "You develop renewables and have room for one 100 MW project. The headline megawatts match.\n\nEIA's 2025 data show wind running at 33.8% of its full potential and solar at 24.0%. Capacity factor is actual output divided by the maximum possible output. On the grid, megawatts tell you size; capacity factor tells you how much energy you really get.", "sources": [{"url": "https://eia.gov/electricity/annual/html/epa_04_08_b.html", "label": "EIA, capacity factors for non-fossil generators"}]}, "evidence": {"kind": "faceOff", "prompt": "Which 100 MW plant made more energy per year at 2025 US averages?", "left": {"name": "100 MW of wind", "note": "33.8% capacity factor"}, "right": {"name": "100 MW of solar", "note": "24.0% capacity factor"}, "correctIndex": 0, "explanation": "At 33.8% versus 24.0%, the wind farm makes about 40% more energy from the same megawatts."}, "numbers": {"kind": "numberSense", "prompt": "At a 24% capacity factor, about how many thousand MWh does 100 MW of solar make in a year?", "min": 0, "max": 600, "value": 210, "unit": "K MWh", "explanation": "100 MW times 8,760 hours times 0.24 is about 210,000 MWh."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks which project gives more energy per megawatt.", "prompt": "What do you answer?", "options": ["They are equal at 100 MW each", "Wind, by about 40% at US averages", "Solar, since its panels are newer"], "correctIndex": 1, "consequences": ["Equal megawatts, unequal energy.", "33.8% over 24.0% is about 1.4 times.", "Newness does not set capacity factor."], "explanation": "Capacity factor converts the same megawatts into different amounts of energy."}, "proReasoning": "Analysts state the energy gap as a number. \"About 40% more\" is precise and persuasive.", "commonMistake": "Treating equal megawatts as equal energy.", "mentalModel": "Quote the energy gap."}, "invest": {"call": {"kind": "theCall", "situation": "Both projects cost about the same to build.", "prompt": "What else must you check before choosing?", "options": ["Which one has a nicer brand name", "Which one has more megawatts", "When each one's power is worth most"], "correctIndex": 2, "consequences": ["Brand does not set revenue.", "Megawatts are equal here.", "Timing and price per hour shape revenue."], "explanation": "Energy volume matters, but so does when it is delivered and at what price."}, "proReasoning": "Investors combine how much and when. Capacity factor is the first half.", "commonMistake": "Stopping at capacity factor without asking about timing.", "mentalModel": "How much, then when."}, "build_startup": {"call": {"kind": "theCall", "situation": "Developers choose projects without good energy estimates.", "prompt": "What could your startup sell?", "options": ["Site-level output forecasts by technology", "A directory of solar panel brands and models", "Larger nameplate equipment for each site"], "correctIndex": 0, "consequences": ["Better energy estimates improve decisions.", "Brands are easy to find.", "Bigger nameplate does not fix estimates."], "explanation": "Analysts turn megawatts into megawatt-hours. Tools that do it per site help developers choose."}, "proReasoning": "Founders sell better numbers to people making big bets. Output forecasts are one.", "commonMistake": "Selling equipment when the gap is information.", "mentalModel": "Sell better numbers."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why would a 100 MW wind farm make more power than a 100 MW solar farm?", "prompt": "What's the reason?", "options": ["Solar panels turn off in summer", "Wind can blow at night; sun cannot shine", "Wind turbines are always much bigger"], "correctIndex": 1, "consequences": ["Solar runs best in summer.", "More running hours, more energy.", "Size is fixed at 100 MW here."], "explanation": "Wind can produce at any hour; solar is limited to daylight."}, "proReasoning": "Think in hours. A plant that can run more hours makes more energy.", "commonMistake": "Assuming the same size means the same output.", "mentalModel": "Hours make energy."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8a84970e0707$ml$]::text[]),
($ml$9383c550-274f-539f-a2c6-ad7d812ab996$ml$::uuid, $ml$cleanenergy$ml$, 11, 1, $ml${"id": "cleanenergy-d11-c1", "title": "The duties move to India and Laos", "lessonTitle": "Tariffs up to 3,521%", "slot": 1, "type": "apply", "brief": {"headline": "In September 2026, the US set final antidumping duties on solar cells from India, Indonesia and Laos. India's combined rate reached 249.13%, and in October the trade commission found US makers were harmed.", "kicker": "Apply the tariff pattern to the next set of countries.", "fullText": "US manufacturers including First Solar, Hanwha Qcells USA and Mission Solar petitioned in August 2025. Commerce's final antidumping margins were 123.04% for India, 94.36% for Indonesia and 65.43% for Laos. Adding a 126.09% countervailing duty, India's total reached 249.13%.\n\nOn October 14, 2026, the US International Trade Commission voted 5 to 0 that the imports injured US industry, clearing the way for duty orders.", "sources": [{"url": "https://gcn.com/?p=21904", "label": "Commerce finalizes dumping duties reaching 249.13% on solar cells from India, Indonesia and Laos"}, {"url": "https://www.pv-tech.org/us-releases-preliminary-antidumping-duties-on-pv-cells-from-india-indonesia-and-laos/", "label": "PV Tech, preliminary antidumping duties on India, Indonesia and Laos"}, {"url": "https://www.usitc.gov/press_room/news_release/2026/er1014_69351.htm", "label": "USITC, solar cells from India, Indonesia and Laos, Oct 2026"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which country faced the highest final antidumping margin?", "options": ["Indonesia, at 94.36%", "Laos, at 65.43%", "India, at 123.04%"], "correctIndex": 2, "explanation": "India's 123.04% antidumping margin, plus a 126.09% countervailing duty, totals 249.13%."}, "numbers": {"kind": "numberSense", "prompt": "What was India's combined antidumping and countervailing duty rate, in percent?", "min": 0, "max": 400, "value": 249, "unit": "%", "explanation": "249.13%: 123.04% antidumping plus 126.09% countervailing."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A developer asks you to explain the new duties in one line.", "prompt": "What do you say?", "options": ["Cells from three new countries now face steep duties", "All solar imports into the US are now banned outright", "Only Chinese-made cells face any US duties at all"], "correctIndex": 0, "consequences": ["India, Indonesia and Laos face rates up to 249%.", "Duties raise costs; they do not ban.", "These target three other countries."], "explanation": "After the 2025 duties on four Southeast Asian countries, the next case hit India, Indonesia and Laos."}, "proReasoning": "People who track trade cases see the pattern: duties move with production. That makes you useful to developers.", "commonMistake": "Thinking one tariff round settles where panels come from.", "mentalModel": "Track where the duties move next."}, "invest": {"call": {"kind": "theCall", "situation": "You own shares in First Solar, one of the petitioners.", "prompt": "What do the duties likely mean for it?", "options": ["No effect on any US maker at all", "Less low-priced import competition in the US", "Higher costs for the cells it buys abroad"], "correctIndex": 1, "consequences": ["The ITC found US industry was harmed.", "Duties protect US makers from cheaper imports.", "It petitioned because duties help it."], "explanation": "Duties on imports protect US factories, while raising costs for developers buying those cells."}, "proReasoning": "Investors map winners and losers of a duty. US makers gain; developers buying imports pay more.", "commonMistake": "Treating a tariff as good or bad for the whole industry.", "mentalModel": "Duties pick winners and losers."}, "build_startup": {"call": {"kind": "theCall", "situation": "Duty rates differ by country and company and keep changing.", "prompt": "What product helps buyers?", "options": ["A ranked list of the sunniest US states", "A new panel cleaning service for farms", "A tool comparing landed costs by supplier"], "correctIndex": 2, "consequences": ["Sunshine does not change duties.", "Cleaning does not touch sourcing.", "Buyers need the all-in cost after duties."], "explanation": "Tariffs vary by company and country. Landed cost tools help buyers decide."}, "proReasoning": "Founders turn complex rules into a simple number buyers need: cost delivered.", "commonMistake": "Building for a problem the rules did not create.", "mentalModel": "Turn rules into landed cost."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why did the US target India, Indonesia and Laos after Southeast Asia?", "prompt": "What's the pattern?", "options": ["Duties push production to new countries", "These countries invented solar cells", "Prices there were too high"], "correctIndex": 0, "consequences": ["Each round moves factories, then a new case follows.", "They did not invent solar cells.", "The claim was prices too low."], "explanation": "Tariffs move factories from country to country faster than they stop imports."}, "proReasoning": "Trade cases chase production. When one country is hit, output moves, and the next case follows.", "commonMistake": "Thinking a tariff ends the flow of imports.", "mentalModel": "Tariffs move factories."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:12dc19d3b097$ml$]::text[]),
($ml$65912851-f725-566c-8488-3aa7cea8a3f9$ml$::uuid, $ml$cleanenergy$ml$, 11, 2, $ml${"id": "cleanenergy-d11-c2", "title": "Why the factories moved south", "lessonTitle": "Tariffs up to 3,521%", "slot": 2, "type": "connect", "brief": {"headline": "In 2025, the US hit solar goods from Cambodia, Malaysia, Thailand and Vietnam with duties up to 3,521%. Those four supplied about 77% of US module imports, and many factories there were Chinese-owned.", "kicker": "Connect day 9 and day 11: concentration and tariffs keep reshaping the map.", "fullText": "On day 9 you saw China hold over 80% of every stage of solar manufacturing.\n\nOn day 11, Chinese-owned factories had opened across Southeast Asia amid US-China trade tensions. The US imported $12.9 billion of solar equipment from the four countries. US makers argued they sold below cost with unfair subsidies, and Commerce set rates company by company, from 14.64% up to 3,521%.", "sources": [{"url": "https://fortune.com/asia/2025/04/22/us-solar-panel-tariffs-southeast-asia-cambodia/", "label": "Fortune, US solar tariffs on Southeast Asia"}, {"url": "https://iea.org/reports/solar-pv-global-supply-chains/executive-summary", "label": "IEA, Solar PV global supply chains"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the pattern in order.", "steps": ["China dominates solar manufacturing", "US tariffs hit Chinese-made goods", "Chinese-owned factories open in Southeast Asia", "The US hits those countries with duties too"], "explanation": "Concentration met trade tension, production moved, and the duties followed."}, "numbers": {"kind": "numberSense", "prompt": "What share of US module imports came from the four Southeast Asian countries?", "min": 0, "max": 100, "value": 77, "unit": "%", "explanation": "About 77%, worth $12.9 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks why US duties target Southeast Asia, not just China.", "prompt": "What is the sharpest answer?", "options": ["China stopped making solar panels entirely", "Chinese-owned makers moved production there", "Southeast Asia invented the solar panel"], "correctIndex": 1, "consequences": ["China still leads every stage.", "Factories followed tariffs to new countries.", "Origin of invention is not the reason."], "explanation": "Production moved south amid US-China tensions, and duties followed it."}, "proReasoning": "Connecting ownership to location shows you understand trade cases. The factory flag and the owner can differ.", "commonMistake": "Reading a country of export as the whole story.", "mentalModel": "Follow the owner, not just the flag."}, "invest": {"call": {"kind": "theCall", "situation": "A developer you back relied on Vietnamese modules.", "prompt": "What risk did it face?", "options": ["A shortage of US sunshine", "Lower power prices from tariffs", "A sudden jump in module costs"], "correctIndex": 2, "consequences": ["Sunshine is not affected.", "Tariffs raise costs, not cut prices.", "Duties raised the cost of its main supply."], "explanation": "With 77% of imports from four countries, duties there hit developer costs hard."}, "proReasoning": "Investors check supplier concentration in a portfolio. One duty can hit most of the supply.", "commonMistake": "Ignoring where a developer's modules come from.", "mentalModel": "Concentrated supply, concentrated risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Buyers must know who owns a factory, not just where it is.", "prompt": "What could your startup offer?", "options": ["Supplier ownership and origin data", "A new module brand from Vietnam", "Cheaper shipping from Malaysia"], "correctIndex": 0, "consequences": ["Ownership matters for duties and rules.", "A new brand faces the same duties.", "Shipping does not avoid duties."], "explanation": "Duties and rules depend on origin and ownership, so data on both is valuable."}, "proReasoning": "Founders sell clarity on complex supply chains. Ownership data is hard to find and needed.", "commonMistake": "Trying to route around rules instead of helping buyers comply.", "mentalModel": "Sell supply chain clarity."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why did Cambodia get a 3,521% duty?", "prompt": "What's the main reason?", "options": ["It made the most panels in the world", "It stopped cooperating with the probe", "Its panels were the lowest quality"], "correctIndex": 1, "consequences": ["China makes the most.", "Non-cooperation leads to the harshest rates.", "Duties are about pricing, not quality."], "explanation": "Four Cambodian makers got 3,521% after Cambodia stopped cooperating with the investigation."}, "proReasoning": "Rates are set company by company. Refusing to cooperate brings the worst outcome.", "commonMistake": "Assuming huge rates reflect huge dumping alone.", "mentalModel": "Cooperation shapes the rate."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:92306d61d2c8$ml$]::text[]),
($ml$4a8968e7-4ba0-577f-94da-731d9c565cdd$ml$::uuid, $ml$cleanenergy$ml$, 11, 3, $ml${"id": "cleanenergy-d11-c3", "title": "Modules from Vietnam, duties at the dock", "lessonTitle": "Tariffs up to 3,521%", "slot": 3, "type": "decide", "brief": {"headline": "You develop US solar farms with modules from Vietnam. New duties hit equipment from four Southeast Asian countries, which supplied about $12.9 billion of US imports.", "kicker": "Decide: what do you do with your project pipeline?", "fullText": "Your next three solar farms were priced on Vietnamese modules. In April 2025, Commerce set antidumping and countervailing duties on solar equipment from Cambodia, Malaysia, Thailand and Vietnam.\n\nAntidumping duties target goods sold below fair value; countervailing duties target subsidies. Rates are set company by company, from 14.64% for Hanwha cells made in Malaysia up to 3,521%. Refunds later are uncertain, and duties apply now.", "sources": [{"url": "https://fortune.com/asia/2025/04/22/us-solar-panel-tariffs-southeast-asia-cambodia/", "label": "Fortune, US solar tariffs on Southeast Asia"}]}, "evidence": {"kind": "sortSignal", "prompt": "Antidumping or countervailing duty?", "buckets": ["Antidumping", "Countervailing"], "items": [{"text": "Targets goods sold below fair value", "bucket": 0}, {"text": "Answers a claim of selling below cost", "bucket": 0}, {"text": "Targets unfair government subsidies", "bucket": 1}, {"text": "Offsets support a state gave the maker", "bucket": 1}], "explanation": "Antidumping duties address pricing below fair value. Countervailing duties offset subsidies."}, "numbers": {"kind": "numberSense", "prompt": "About how many billion dollars of solar equipment did the US import from the four countries?", "min": 0, "max": 40, "value": 13, "unit": "B", "explanation": "About $12.9 billion, roughly 77% of US module imports."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO asks what to do with the three projects.", "prompt": "What do you recommend?", "options": ["Keep importing modules and hope for refunds", "Cancel all three of the projects today", "Re-source modules and reprice the projects"], "correctIndex": 2, "consequences": ["Duties apply now; refunds are uncertain.", "You walk away from viable projects.", "You adjust costs and keep building."], "explanation": "New duties change costs. Developers re-source and reprice rather than gamble or quit."}, "proReasoning": "Strong developers respond with a plan, not a bet. Re-sourcing protects the pipeline.", "commonMistake": "Hoping a duty goes away on its own.", "mentalModel": "Re-source, reprice, keep building."}, "invest": {"call": {"kind": "theCall", "situation": "You fund the developer. Module costs just jumped.", "prompt": "What do you ask management?", "options": ["How costs change under new suppliers", "Whether it can ignore the duties", "Whether solar demand has collapsed"], "correctIndex": 0, "consequences": ["That shows the real hit to returns.", "Duties cannot be ignored.", "Demand is not the issue here."], "explanation": "The question is how much costs rise after re-sourcing, and whether the projects still work."}, "proReasoning": "Investors ask for the new cost stack after a shock. Numbers beat reassurances.", "commonMistake": "Accepting \"we'll manage\" without new figures.", "mentalModel": "Ask for the new cost stack."}, "build_startup": {"call": {"kind": "theCall", "situation": "Developers scramble to find modules not hit by the duties.", "prompt": "What could your startup offer them?", "options": ["More factories in Vietnam", "A marketplace of compliant module supply", "A way to hide where modules came from"], "correctIndex": 1, "consequences": ["Vietnam is under the duties.", "Matching buyers to compliant supply is valuable.", "Hiding origin is illegal and risky."], "explanation": "Tariffs vary by company and country, so helping buyers find compliant supply helps."}, "proReasoning": "Founders help buyers comply fast. A shock to supply creates demand for matching.", "commonMistake": "Building anything that relies on evading rules.", "mentalModel": "Help them comply fast."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why do duty rates differ so much between companies?", "prompt": "What's the answer?", "options": ["Rates are chosen at random", "Bigger companies always pay more", "Each company is assessed on its own"], "correctIndex": 2, "consequences": ["They follow investigations.", "Size alone does not set the rate.", "Pricing and cooperation vary by company."], "explanation": "Rates are set company by company, from 14.64% to 3,521%."}, "proReasoning": "Trade duties are tailored. The same country can see very different rates.", "commonMistake": "Assuming one country gets one rate.", "mentalModel": "Company by company."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:dbf7331d50f3$ml$]::text[]),
($ml$3c207c15-21a0-5ec9-97c7-ed486fb154a1$ml$::uuid, $ml$cleanenergy$ml$, 12, 1, $ml${"id": "cleanenergy-d12-c1", "title": "Stopped at 80% done", "lessonTitle": "When offshore wind stopped adding up", "slot": 1, "type": "apply", "brief": {"headline": "On August 22, 2025, US regulators ordered work to stop on Revolution Wind, a 704 MW offshore wind farm that was about 80% complete. A judge lifted the order a month later.", "kicker": "Apply the offshore wind risk to a project almost finished.", "fullText": "Revolution Wind, an Ørsted joint venture, had 45 of its 65 turbines installed and all foundations in place. It held 20-year power contracts for 400 MW to Rhode Island and 304 MW to Connecticut, and aimed to start operating in the second half of 2026.\n\nThe Bureau of Ocean Energy Management issued the stop-work order. On September 22, 2025, a federal court in Washington granted a preliminary injunction, and work could resume while the lawsuit went on.", "sources": [{"url": "https://www.offshorewind.biz/2025/08/23/breaking-trump-administration-stops-construction-on-80-pct-complete-offshore-wind-farm", "label": "offshoreWIND.biz, stop-work order on Revolution Wind"}, {"url": "https://offshorewind.biz/2025/09/22/offshore-construction-work-resumes-on-revolution-wind-after-us-judges-ruling", "label": "offshoreWIND.biz, Revolution Wind work resumes after ruling"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["45 of 65 turbines were installed.", "The project had no buyers for its power.", "A judge lifted the order in September 2025."], "fakeIndex": 1, "explanation": "It held 20-year contracts with Rhode Island and Connecticut for all 704 MW."}, "numbers": {"kind": "numberSense", "prompt": "What share of its 65 turbines did Revolution Wind have installed when work was stopped?", "min": 0, "max": 100, "value": 69, "unit": "%", "explanation": "45 of 65 is about 69% of turbines, with the project about 80% complete overall."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at an offshore wind developer. They ask what risk Revolution Wind showed.", "prompt": "What is your answer?", "options": ["Contracted power always gets cancelled later", "Permits can be challenged even late in a build", "Offshore turbines simply cannot work at sea"], "correctIndex": 1, "consequences": ["Its contracts stayed in place.", "An 80% complete project was halted.", "Turbines work; this was a permit issue."], "explanation": "Even a nearly finished project with contracts faced a federal halt."}, "proReasoning": "Offshore wind pros talk about permit and policy risk alongside cost. It decides schedules.", "commonMistake": "Treating a signed permit as risk-free.", "mentalModel": "Permits can move late."}, "invest": {"call": {"kind": "theCall", "situation": "You hold debt in an offshore wind farm stopped mid-build.", "prompt": "What drives your loss if the halt lasts?", "options": ["Turbine prices fall during the halt", "The power contracts pay more per day", "Costs keep running while no power is sold"], "correctIndex": 2, "consequences": ["Prices do not refund sunk costs.", "Contracts pay for power delivered.", "Capital sits idle, and interest keeps adding up."], "explanation": "Capital-heavy projects bleed money when delayed, because the fuel is free but the money is not."}, "proReasoning": "Investors in capital-heavy projects fear delay above all. Interest runs while revenue waits.", "commonMistake": "Focusing on turbine costs when time is the real cost.", "mentalModel": "Delay is the costliest risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Developers need to track legal and permit risk across projects.", "prompt": "What could your startup offer?", "options": ["Tracking of permit challenges and rulings", "Bigger offshore wind turbines for the site", "A new database of fish species at sea"], "correctIndex": 0, "consequences": ["Permit risk now shapes schedules.", "Size was not the issue.", "Useful elsewhere, not this need."], "explanation": "A stop-work order and court ruling decided this schedule. Tracking that risk is valuable."}, "proReasoning": "Founders see legal risk as data that can be tracked and priced.", "commonMistake": "Building only for engineering risks.", "mentalModel": "Track the legal risk."}, "curiosity": {"call": {"kind": "theCall", "situation": "How can a nearly finished wind farm be stopped?", "prompt": "What happened here?", "options": ["The states refused to buy the power", "A federal agency issued a stop-work order", "The turbines fell into the sea"], "correctIndex": 1, "consequences": ["The states held 20-year contracts.", "BOEM ordered the halt; a court later lifted it.", "Turbines stood; work paused."], "explanation": "The Bureau of Ocean Energy Management ordered work to stop; a judge lifted it in September 2025."}, "proReasoning": "Big projects depend on permits until the last turbine. Policy can intervene at any stage.", "commonMistake": "Assuming once building starts, finishing is certain.", "mentalModel": "Permits matter to the last turbine."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:ad8239005686$ml$]::text[]),
($ml$a9d30730-26f0-5244-b13b-251262f95313$ml$::uuid, $ml$cleanenergy$ml$, 12, 2, $ml${"id": "cleanenergy-d12-c2", "title": "Interest rates in the cost per MWh", "lessonTitle": "When offshore wind stopped adding up", "slot": 2, "type": "connect", "brief": {"headline": "In 2023, Ørsted cancelled Ocean Wind 1 and 2 off New Jersey and took a $4 billion impairment. Offshore wind is paid back over decades, so higher interest rates raise its cost per MWh.", "kicker": "Connect day 7 and day 12: financing sits inside LCOE.", "fullText": "On day 7 you saw that LCOE spreads a plant's lifetime building, running and financing costs over its output. For a plant with free fuel, financing is a big share.\n\nOn day 12, Ørsted blamed supply chain problems, delays and rising interest rates. Ocean Wind 1 alone would have had 98 turbines and powered about 500,000 homes, and accounted for $2.8 billion of the impairment. Developers had signed power prices before costs rose.", "sources": [{"url": "https://www.cnbc.com/2023/11/01/orsted-axes-two-new-jersey-wind-projects-takes-4-billion-writedown.html", "label": "CNBC, Ørsted axes two New Jersey wind projects"}, {"url": "https://www.pv-tech.org/us-utility-scale-solar-pv-lcoe-tightens-to-us38-78-mwh-in-2025-lazard/", "label": "PV Tech, Lazard 2025 LCOE for US solar"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why do rising interest rates hit offshore wind harder than a gas plant?", "options": ["Its turbines use more fuel when rates rise", "Gas plants are exempt from interest", "Most of its cost is paid upfront and borrowed"], "correctIndex": 2, "explanation": "Offshore wind is capital-heavy with free fuel, so financing makes up much of its cost per MWh."}, "numbers": {"kind": "numberSense", "prompt": "How many turbines would Ocean Wind 1 alone have had?", "min": 0, "max": 300, "value": 98, "explanation": "98 turbines, enough for about 500,000 homes."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks how interest rates enter a wind farm's LCOE.", "prompt": "What is the best answer?", "options": ["Interest rates change the wind speed", "LCOE ignores how a plant is financed", "Financing costs are part of lifetime cost"], "correctIndex": 2, "consequences": ["Wind speed is unaffected.", "LCOE includes financing.", "Higher rates raise cost per MWh."], "explanation": "LCOE divides lifetime building, running and financing costs by output. Rates raise financing."}, "proReasoning": "Project finance people know the fuel is free but the money is not. Rates set the real price.", "commonMistake": "Thinking renewables are immune to interest rates because fuel is free.", "mentalModel": "Free fuel, costly money."}, "invest": {"call": {"kind": "theCall", "situation": "Rates are rising. You own a solar farm and an offshore wind project.", "prompt": "Which loses more value?", "options": ["The offshore wind project", "The solar farm, which uses no fuel", "Neither, since both use free fuel"], "correctIndex": 0, "consequences": ["Bigger upfront cost, longer payback, more rate pain.", "Both use free fuel; size of capital differs.", "Free fuel does not shield financing."], "explanation": "Projects with big upfront costs and long paybacks lose value fastest when rates rise."}, "proReasoning": "Investors rank assets by rate sensitivity. Capital intensity and payback length drive it.", "commonMistake": "Treating all renewables as equally rate-sensitive.", "mentalModel": "Capital-heavy means rate-sensitive."}, "build_startup": {"call": {"kind": "theCall", "situation": "Delays raised financing costs on offshore projects.", "prompt": "Which product cuts that cost?", "options": ["Longer power contracts at fixed prices", "Tools that cut construction time and risk", "Cheaper fuel for wind turbines"], "correctIndex": 1, "consequences": ["Fixed prices were part of the trap.", "Less time borrowing means lower cost.", "Wind needs no fuel."], "explanation": "Delays and supply problems sank these projects. Cutting build risk lowers financing costs."}, "proReasoning": "Founders shorten the time money is tied up. That lowers cost per MWh directly.", "commonMistake": "Solving fuel for a technology that has none.", "mentalModel": "Shorter builds, cheaper money."}, "curiosity": {"call": {"kind": "theCall", "situation": "Wind is free, so why did these wind farms become too expensive?", "prompt": "What's the answer?", "options": ["Turbines must pay for all the wind they use", "New Jersey charged a fee for ocean wind", "They cost a lot upfront, paid with costly loans"], "correctIndex": 2, "consequences": ["Wind is free; money is not.", "Nothing like that was charged.", "Upfront cost plus interest drives the price."], "explanation": "Offshore wind is costly to build and paid back over decades. Higher rates raise the cost of waiting."}, "proReasoning": "Free fuel does not mean free power. Money has a price too.", "commonMistake": "Equating free fuel with cheap electricity.", "mentalModel": "Money is the fuel."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:bb64a1974b7d$ml$]::text[]),
($ml$a1009b0d-6340-5660-a6d3-ea9fc6b6085e$ml$::uuid, $ml$cleanenergy$ml$, 12, 3, $ml${"id": "cleanenergy-d12-c3", "title": "A fixed price meets rising costs", "lessonTitle": "When offshore wind stopped adding up", "slot": 3, "type": "decide", "brief": {"headline": "You run an offshore wind project with a power price signed years ago. Costs and interest rates have since risen, the trap that led Ørsted to cancel Ocean Wind 1 and 2.", "kicker": "Decide: push ahead, renegotiate or walk away?", "fullText": "Your project signed a fixed price per megawatt-hour before supply chain costs and interest rates climbed. Building now would lose money at that price.\n\nØrsted faced the same squeeze off New Jersey in 2023. It cancelled Ocean Wind 1 and 2 and took a $4 billion impairment, with cancellation fees that could add up to $1.55 billion more. In renewables, the fuel is free but the money is not; interest rates set the real price.", "sources": [{"url": "https://www.cnbc.com/2023/11/01/orsted-axes-two-new-jersey-wind-projects-takes-4-billion-writedown.html", "label": "CNBC, Ørsted axes two New Jersey wind projects"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does it make the fixed-price project better or worse?", "buckets": ["Better", "Worse"], "items": [{"text": "Lower interest rates on its debt", "bucket": 0}, {"text": "A higher price renegotiated with buyers", "bucket": 0}, {"text": "Rising turbine and vessel costs", "bucket": 1}, {"text": "Construction delays of a year", "bucket": 1}], "explanation": "Cheaper money and a better price help. Rising costs and delays squeeze a fixed revenue."}, "numbers": {"kind": "numberSense", "prompt": "About how many thousand homes would Ocean Wind 1 have powered?", "min": 0, "max": 2000, "value": 500, "unit": "K", "explanation": "About 500,000 homes, before it was cancelled."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO asks for options on the money-losing project.", "prompt": "What do you put first?", "options": ["Try to renegotiate the power price", "Build anyway and absorb the losses", "Hide the losses from investors"], "correctIndex": 0, "consequences": ["A better price can save the project.", "Losses at this scale can sink the company.", "That is never an option."], "explanation": "The problem is a fixed price below cost. Fixing the price is the first lever."}, "proReasoning": "Project finance leads attack the revenue side when costs rise. Renegotiation comes before cancellation.", "commonMistake": "Accepting a loss-making contract as fixed forever.", "mentalModel": "Fix the price before quitting."}, "invest": {"call": {"kind": "theCall", "situation": "A developer you hold says it will build despite rising costs.", "prompt": "What should worry you most?", "options": ["The color of the turbine blades", "Revenue fixed below the new cost", "Average wind speeds at the site"], "correctIndex": 1, "consequences": ["Irrelevant to returns.", "That gap is how a $4 billion impairment happens.", "Wind data was known at signing."], "explanation": "Fixed revenue meeting rising costs is the trap that sank Ocean Wind."}, "proReasoning": "Investors watch the gap between locked revenue and moving costs. That gap became a $4 billion write-down.", "commonMistake": "Trusting management to build through a negative margin.", "mentalModel": "Watch the fixed-price gap."}, "build_startup": {"call": {"kind": "theCall", "situation": "Developers sign prices years before building.", "prompt": "What could your startup offer?", "options": ["Bigger turbines for every single project", "A new kind of ocean buoy for wind data", "Cost forecasting before prices are signed"], "correctIndex": 2, "consequences": ["Bigger turbines do not fix pricing.", "Not tied to the pricing risk.", "Better forecasts avoid signing below cost."], "explanation": "Developers signed prices before costs rose. Better forecasts reduce that risk."}, "proReasoning": "Founders attack the moment the mistake is made: signing a price too early.", "commonMistake": "Solving after-the-fact instead of at the decision point.", "mentalModel": "Fix the decision, not the aftermath."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why would a company cancel a project it already planned?", "prompt": "What's the main reason?", "options": ["Building it would lose more than quitting", "Engineers forgot how to build it", "Wind stopped blowing off New Jersey"], "correctIndex": 0, "consequences": ["A $4 billion write-down beat years of losses.", "The know-how existed.", "The wind is still there."], "explanation": "With fixed prices below new costs, cancelling was cheaper than building."}, "proReasoning": "Sometimes the best financial choice is to stop. Sunk costs should not drive the decision.", "commonMistake": "Thinking a started project must always be finished.", "mentalModel": "Stop when the math says stop."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3a92b9fb92d1$ml$]::text[]),
($ml$8366a1cb-702a-5006-9397-aa462f8bc800$ml$::uuid, $ml$cleanenergy$ml$, 13, 1, $ml${"id": "cleanenergy-d13-c1", "title": "Meta keeps a reactor running", "lessonTitle": "Microsoft buys a nuclear plant's output", "slot": 1, "type": "apply", "brief": {"headline": "In June 2025, Meta signed a 20-year deal for 1,121 MW from Constellation's Clinton nuclear plant in Illinois. Deliveries start in June 2027, when a state support program for the plant ends.", "kicker": "Apply the PPA idea to a plant that needed a new buyer.", "fullText": "Illinois' Zero Emission Credit program, paid for by ratepayers, had supported the Clinton plant and expires in mid-2027. Constellation said the Meta agreement essentially replaces it, without ratepayer support.\n\nThe deal also adds 30 MW through upgrades to the plant. Constellation said it preserves 1,100 local jobs and $13.5 million a year in tax revenue. Meta gets long-term carbon-free supply for its operations.", "sources": [{"url": "https://investors.constellationenergy.com/news-releases/news-release-details/constellation-meta-sign-20-year-deal-clean-reliable-nuclear", "label": "Constellation, Constellation and Meta sign 20-year deal (June 2025)"}, {"url": "https://www.orrick.com/en/News/2024/10/Microsoft-Signs-20-Year-PPA-with-Constellation", "label": "Orrick, Microsoft signs 20-year PPA with Constellation"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What did Meta's PPA replace for the Clinton plant?", "options": ["A state program funded by ratepayers", "A loan from the federal government", "Sales to a neighboring country"], "correctIndex": 0, "explanation": "The deal essentially replaces Illinois' Zero Emission Credit program, which expires in mid-2027."}, "numbers": {"kind": "numberSense", "prompt": "How many MW of extra output will upgrades add at Clinton under the deal?", "min": 0, "max": 100, "value": 30, "unit": "MW", "explanation": "30 MW, on top of the 1,121 MW contracted."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview for an energy procurement role at a tech company.", "prompt": "How do you describe the Meta and Clinton deal?", "options": ["A purchase of the whole plant by Meta", "A short-term deal for extra summer power", "A 20-year contract that keeps a plant running"], "correctIndex": 2, "consequences": ["Meta buys output, not the plant.", "It runs 20 years from 2027.", "That is exactly what a long PPA can do."], "explanation": "A PPA buys a plant's output on agreed terms. Here it gave the plant a future after state support ends."}, "proReasoning": "Procurement pros explain what the contract changes for the plant. Here it replaces a subsidy.", "commonMistake": "Confusing buying output with buying the plant.", "mentalModel": "Output under contract, not ownership."}, "invest": {"call": {"kind": "theCall", "situation": "You hold Constellation shares. State support for Clinton ends in 2027.", "prompt": "What does the Meta deal do for the plant?", "options": ["Locks in revenue for 20 years", "Raises the plant's operating costs", "Ends sales to the grid entirely"], "correctIndex": 0, "consequences": ["A strong buyer makes revenue predictable.", "Costs are not the point here.", "Power still flows through the grid."], "explanation": "A 20-year contract with a strong buyer makes revenue predictable and valuable."}, "proReasoning": "Investors prize long contracts with strong buyers. They turn uncertain revenue into steady cash.", "commonMistake": "Overlooking how a subsidy ending changes the plant's value.", "mentalModel": "Contracts replace uncertainty."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup wants to build a new clean power plant.", "prompt": "What does the Clinton deal teach you?", "options": ["Rely on state programs to last forever", "Line up a long-term buyer early", "Build first and look for buyers later"], "correctIndex": 1, "consequences": ["Clinton's program was set to end.", "A committed offtaker makes projects bankable.", "Unsold output is hard to finance."], "explanation": "Energy projects get built and kept running when a buyer commits."}, "proReasoning": "Founders secure the offtaker before the steel. A signed buyer is what lenders want.", "commonMistake": "Treating the buyer as the last step.", "mentalModel": "Find your offtaker first."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why would Meta sign up for a nuclear plant's power for 20 years?", "prompt": "What's the main reason?", "options": ["It plans to run the reactor itself", "Nuclear power is free to buy", "It wants steady carbon-free power"], "correctIndex": 2, "consequences": ["Constellation runs the plant.", "It pays for the power.", "Nuclear runs day and night, carbon-free."], "explanation": "Tech companies want carbon-free power around the clock, and nuclear runs nonstop."}, "proReasoning": "Big tech buys what matches its use: steady, clean, long-term power.", "commonMistake": "Assuming tech firms buy power only from solar and wind.", "mentalModel": "Steady use wants steady supply."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:baaecf9e0c10$ml$]::text[]),
($ml$0db96c47-8307-5edd-9824-902bd5062d2b$ml$::uuid, $ml$cleanenergy$ml$, 13, 2, $ml${"id": "cleanenergy-d13-c2", "title": "Why a 20-year deal fits nuclear", "lessonTitle": "Microsoft buys a nuclear plant's output", "slot": 2, "type": "connect", "brief": {"headline": "Microsoft's 20-year PPA covers Three Mile Island Unit 1, an 835 MW reactor Constellation plans to restart. US nuclear plants ran at a 91.1% capacity factor in 2025.", "kicker": "Connect day 10 and day 13: high capacity factor makes firm contracts work.", "fullText": "On day 10 you saw nuclear run at 91.1% of its full potential in 2025, against 24.0% for solar.\n\nOn day 13, Microsoft signed a 20-year power purchase agreement for Three Mile Island Unit 1, to be restarted as the Crane Clean Energy Center. The reactor closed for economic reasons in 2019. Microsoft can match its data centers' use in PJM with carbon-free power that runs day and night.", "sources": [{"url": "https://www.orrick.com/en/News/2024/10/Microsoft-Signs-20-Year-PPA-with-Constellation", "label": "Orrick, Microsoft signs 20-year PPA with Constellation"}, {"url": "https://eia.gov/electricity/annual/html/epa_04_08_b.html", "label": "EIA, capacity factors for non-fossil generators"}]}, "evidence": {"kind": "faceOff", "prompt": "Which 835 MW plant better matches a data center that runs 24 hours?", "left": {"name": "A nuclear reactor", "note": "About 91% capacity factor"}, "right": {"name": "A solar farm", "note": "About 24% capacity factor"}, "correctIndex": 0, "explanation": "Nuclear runs almost nonstop, so its output tracks round-the-clock use far better."}, "numbers": {"kind": "numberSense", "prompt": "How many MW is Three Mile Island Unit 1?", "min": 0, "max": 2000, "value": 835, "unit": "MW", "explanation": "835 MW, closed in 2019 and planned to restart as the Crane Clean Energy Center."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A colleague asks why Microsoft did not just buy more solar.", "prompt": "What do you answer?", "options": ["Nuclear covers night hours solar cannot", "Solar farms are banned in Pennsylvania", "Nuclear plants need no contract at all"], "correctIndex": 0, "consequences": ["A 91% capacity factor fits 24-hour use.", "Solar is legal there.", "The restart rests on the contract."], "explanation": "Microsoft wants carbon-free power matched to its use, including at night."}, "proReasoning": "Buyers match supply shape to load shape. A flat load wants flat supply.", "commonMistake": "Comparing energy sources on price alone.", "mentalModel": "Match supply shape to load shape."}, "invest": {"call": {"kind": "theCall", "situation": "You assess the value of the Crane restart.", "prompt": "What makes its 20-year contract so valuable?", "options": ["It will run only on the sunny days", "Steady high output sold to a strong buyer", "The plant's location right next to a river"], "correctIndex": 1, "consequences": ["Nuclear runs regardless of weather.", "High capacity factor plus a strong offtaker.", "Location helps cooling, not value here."], "explanation": "High output and a long contract with a strong buyer make revenue predictable."}, "proReasoning": "Investors multiply volume by certainty. Nuclear gives volume; the PPA gives certainty.", "commonMistake": "Valuing the contract without the plant's output profile.", "mentalModel": "Volume times certainty."}, "build_startup": {"call": {"kind": "theCall", "situation": "Tech buyers want carbon-free power every hour, not just on average.", "prompt": "What could your startup offer?", "options": ["More daytime solar contracts and nothing else", "Paper credits that carry no timing data", "Matching clean supply to use hour by hour"], "correctIndex": 2, "consequences": ["Daytime only misses nights.", "Timing is the whole point.", "That is what round-the-clock buyers want."], "explanation": "Buyers like Microsoft want power matched to use. Tools that show hourly matching help."}, "proReasoning": "Founders serve the buyer's real goal: clean power in every hour they use it.", "commonMistake": "Selling yearly averages to buyers who care about hours.", "mentalModel": "Match every hour."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why restart a reactor that closed in 2019?", "prompt": "What changed?", "options": ["A big buyer signed a long contract", "The reactor repaired itself", "Pennsylvania banned other power"], "correctIndex": 0, "consequences": ["Guaranteed revenue made the restart worth it.", "Restarting takes planned work.", "No such ban exists."], "explanation": "A guaranteed buyer makes a costly project easier to finance."}, "proReasoning": "Plants close for economics and reopen for economics. A contract changed the math.", "commonMistake": "Thinking plants reopen for technical reasons alone.", "mentalModel": "A buyer changes the math."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:a223745d0994$ml$]::text[]),
($ml$e6b2d86a-fed5-5057-b87c-5f56b33110eb$ml$::uuid, $ml$cleanenergy$ml$, 13, 3, $ml${"id": "cleanenergy-d13-c3", "title": "Signing for a plant not yet built", "lessonTitle": "Microsoft buys a nuclear plant's output", "slot": 3, "type": "decide", "brief": {"headline": "You develop a new clean power plant and need financing. Lenders ask who will buy the power. Microsoft's 20-year PPA helped justify restarting an 835 MW reactor.", "kicker": "Decide: what do you secure before you start building?", "fullText": "Your project needs hundreds of millions of dollars. Banks want to know the plant will have revenue for decades.\n\nA PPA is a long-term deal to buy power from a specific plant at agreed terms. The buyer gets supply; the seller gets steady revenue it can borrow against. Microsoft's 20-year deal with Constellation helped justify restarting Three Mile Island Unit 1. In energy, a signed buyer is what turns a plan into a plant.", "sources": [{"url": "https://www.orrick.com/en/News/2024/10/Microsoft-Signs-20-Year-PPA-with-Constellation", "label": "Orrick, Microsoft signs 20-year PPA with Constellation"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["A PPA is a long-term deal to buy a plant's power.", "A PPA gives the seller steady revenue.", "A PPA means the buyer owns the plant."], "fakeIndex": 2, "explanation": "The buyer, or offtaker, agrees to take the output. Ownership stays with the seller."}, "numbers": {"kind": "numberSense", "prompt": "How many years does the Microsoft and Constellation PPA run?", "min": 0, "max": 50, "value": 20, "unit": "years", "explanation": "20 years, long enough to justify the restart."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO asks what to do before breaking ground.", "prompt": "What do you recommend?", "options": ["Wait until power prices spike", "Sign a long-term buyer for the power", "Order turbines and find buyers later"], "correctIndex": 1, "consequences": ["Timing the market is a gamble.", "An offtaker makes the project financeable.", "Unsold output scares lenders."], "explanation": "A guaranteed buyer makes a costly project easier to finance."}, "proReasoning": "Developers sequence the work: buyer, then financing, then construction.", "commonMistake": "Building on hope that buyers will appear.", "mentalModel": "Buyer, then money, then steel."}, "invest": {"call": {"kind": "theCall", "situation": "A developer asks you to fund a plant with no buyer signed.", "prompt": "What do you ask for?", "options": ["A larger plant design to cut costs", "A promise that prices will rise", "A signed offtaker before you commit"], "correctIndex": 2, "consequences": ["Size does not secure revenue.", "Promises are not contracts.", "Contracted revenue lowers your risk."], "explanation": "Without a PPA, the plant's revenue is uncertain and harder to finance."}, "proReasoning": "Investors want revenue on paper. A PPA is the paper.", "commonMistake": "Funding projects on forecasts alone.", "mentalModel": "Revenue on paper."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your first plant needs a buyer, and big tech buys most clean power.", "prompt": "Who do you approach?", "options": ["A large buyer with steady power needs", "Homeowners nearby, one at a time", "Other startups that have no revenue yet"], "correctIndex": 0, "consequences": ["A strong offtaker makes you bankable.", "Too small to finance a plant.", "Weak buyers do not reassure lenders."], "explanation": "A strong buyer's contract is what lenders finance against."}, "proReasoning": "Founders pitch buyers lenders trust. The offtaker's credit becomes the project's credit.", "commonMistake": "Signing weak buyers to have any buyer.", "mentalModel": "Strong buyer, strong project."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why do power plants sign contracts before they exist?", "prompt": "What's the reason?", "options": ["Contracts make the plant cheaper to run", "Banks lend against guaranteed sales", "Laws ban plants without contracts"], "correctIndex": 1, "consequences": ["Running costs stay the same.", "Steady revenue makes lending safer.", "No such law exists."], "explanation": "A signed buyer is what turns a plan into a plant."}, "proReasoning": "Money follows certainty. Contracts create it.", "commonMistake": "Thinking contracts come after construction.", "mentalModel": "Certainty brings in the money."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8bb5901afd56$ml$]::text[]),
($ml$af81e28f-caaf-55a4-a67a-dce8c7838d05$ml$::uuid, $ml$cleanenergy$ml$, 14, 1, $ml${"id": "cleanenergy-d14-c1", "title": "Three quarters of rising prices", "lessonTitle": "What a solar PPA costs", "slot": 1, "type": "apply", "brief": {"headline": "In the third quarter of 2025, North American solar PPA prices rose 4% to $59.77 per MWh, LevelTen reported. Wind reached $74.69, and both were the highest since at least 2023.", "kicker": "Apply PPA pricing to a quarter of policy worries.", "fullText": "It was the third straight quarter of increases in LevelTen's market-averaged index. Developers cited growing policy uncertainty, tighter rules on foreign suppliers, tariffs on parts needed to build modules, and a pending trade case on cells from India and other Asian countries.\n\nDevelopers were also rushing to safe-harbor projects for tax credits, which LevelTen said would preserve only a finite amount of planned capacity.", "sources": [{"url": "https://www.pv-tech.org/north-american-solar-ppa-prices-up-4-q3-amid-policy-headwinds/", "label": "PV Tech, North American solar PPA prices up 4% in Q3 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What mainly pushed PPA prices up in Q3 2025?", "options": ["A sudden shortage of sunshine in 2025", "Buyers asking to pay more for power", "Policy and trade uncertainty raising costs"], "correctIndex": 2, "explanation": "LevelTen pointed to policy uncertainty, foreign supplier rules, tariffs and a pending trade case."}, "numbers": {"kind": "numberSense", "prompt": "To the nearest dollar, what was the Q3 2025 North American wind PPA price per MWh?", "min": 0, "max": 200, "value": 75, "unit": "$", "explanation": "About $75: $74.69 per MWh, against $59.77 for solar."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks why solar contracts keep getting pricier.", "prompt": "What is your answer?", "options": ["Policy risk raises developers' costs", "Solar panels became very scarce", "Buyers prefer higher prices"], "correctIndex": 0, "consequences": ["Tariffs and rules add cost and uncertainty.", "Panels were plentiful and cheap.", "Buyers prefer lower prices."], "explanation": "The price buyers pay reflects project risk as much as panel cost."}, "proReasoning": "Analysts explain PPA prices with risk, not just hardware. That is what moved in 2025.", "commonMistake": "Linking PPA prices only to module prices.", "mentalModel": "Risk moves the price."}, "invest": {"call": {"kind": "theCall", "situation": "You back a solar developer. PPA prices rose three quarters in a row.", "prompt": "What does that tell you?", "options": ["Demand for solar power has collapsed", "Costs and risks are rising for projects", "Its profits are now guaranteed to rise"], "correctIndex": 1, "consequences": ["Buyers are still signing.", "Higher prices largely pass through costs.", "Rising costs can eat the gain."], "explanation": "Rising PPA prices reflect higher costs and risk, not automatically higher margins."}, "proReasoning": "Investors ask whether price rises are margin or pass-through. Here they were mostly costs.", "commonMistake": "Reading higher prices as higher profits.", "mentalModel": "Price up is not margin up."}, "build_startup": {"call": {"kind": "theCall", "situation": "Uncertain supplier rules are raising project costs.", "prompt": "What could your startup sell?", "options": ["A guide to sunny project sites", "Fewer contracts for buyers", "Tools to check supplier compliance"], "correctIndex": 2, "consequences": ["Sunshine was not the issue.", "Buyers want more options.", "Compliance checks cut a key risk."], "explanation": "Supplier rules raise costs. Tools that check compliance help developers move faster."}, "proReasoning": "Founders target the cost that is rising fastest. In 2025 it was policy risk.", "commonMistake": "Solving the part of the cost that is falling.", "mentalModel": "Target the rising cost."}, "curiosity": {"call": {"kind": "theCall", "situation": "Solar panels are cheap. Why are solar contracts getting pricier?", "prompt": "What's the best explanation?", "options": ["Rules and tariffs make projects riskier", "Panels got much more costly this year", "The sun got weaker during 2025"], "correctIndex": 0, "consequences": ["Risk adds to price beyond the hardware.", "Panels were at record lows.", "The sun is unchanged."], "explanation": "Contract prices carry project risk, not just equipment cost."}, "proReasoning": "A contract price bundles many costs. Hardware is only one.", "commonMistake": "Expecting cheaper panels to mean cheaper contracts.", "mentalModel": "Contracts price the risk."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:11199b0c50fc$ml$]::text[]),
($ml$7500bb2d-92d6-5fd7-8cdb-63f5bf425e0b$ml$::uuid, $ml$cleanenergy$ml$, 14, 2, $ml${"id": "cleanenergy-d14-c2", "title": "Tariffs in the contract price", "lessonTitle": "What a solar PPA costs", "slot": 2, "type": "connect", "brief": {"headline": "North American solar PPAs averaged $61.67 per MWh in Q4 2025, up 9% in a year. Europe fell to €57.44, and US developers cited a tariff investigation among the reasons.", "kicker": "Connect day 11 and day 14: tariffs flow into contract prices.", "fullText": "On day 11 you saw the US set duties of up to 3,521% on solar equipment from four Southeast Asian countries that supplied about 77% of US module imports.\n\nOn day 14, LevelTen showed the effect in contracts. US developers cited uncertainty over a tariff investigation, stalled federal permitting and confusing rules on foreign suppliers. In Europe, where supply outpaced demand, solar PPA prices kept falling.", "sources": [{"url": "https://www.pv-tech.org/north-american-solar-ppa-prices-climb-us61-67-mwh-european-prices-continue-fall/", "label": "PV Tech, North American solar PPA prices climb to $61.67/MWh"}, {"url": "https://fortune.com/asia/2025/04/22/us-solar-panel-tariffs-southeast-asia-cambodia/", "label": "Fortune, US solar tariffs on Southeast Asia"}]}, "evidence": {"kind": "buildChain", "prompt": "Trace how a tariff reaches the buyer.", "steps": ["The US puts duties on imported modules", "Developers pay more for equipment", "Projects cost more and carry more risk", "Developers raise their PPA prices"], "explanation": "Duties raise equipment costs and risk, and developers pass them into contract prices."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did North American solar PPA prices rise from Q4 2024 to Q4 2025?", "min": 0, "max": 30, "value": 9, "unit": "%", "explanation": "Up 9%, to $61.67 per MWh."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In an interview, you are asked why US and European solar PPAs diverged.", "prompt": "What is your answer?", "options": ["US buyers asked to pay higher prices", "US risk rose while Europe had a surplus", "Europe has far more sunshine all year"], "correctIndex": 1, "consequences": ["Buyers do not ask to pay more.", "Tariffs and rules lifted US costs.", "The US is sunnier on average."], "explanation": "US tariff and permit uncertainty raised costs; Europe saw supply outpace demand."}, "proReasoning": "Explaining regional gaps with policy shows real market insight.", "commonMistake": "Blaming the weather for a policy-driven gap.", "mentalModel": "Policy explains the gap."}, "invest": {"call": {"kind": "theCall", "situation": "You can fund solar in the US or in Europe.", "prompt": "What should you weigh?", "options": ["Only which of the two regions has more sun", "Only the cost of the panels in each region", "US policy risk against higher US prices"], "correctIndex": 2, "consequences": ["Sun is one factor among many.", "Panels cost about the same.", "Higher prices may reward higher risk."], "explanation": "Rising US PPA prices reflect tariff and permitting risk. Weigh both sides."}, "proReasoning": "Investors pair price with risk. A higher price can be fair pay for more uncertainty.", "commonMistake": "Chasing the higher price without pricing the risk.", "mentalModel": "Price and risk travel together."}, "build_startup": {"call": {"kind": "theCall", "situation": "Tariffs make it hard to know a project's real cost.", "prompt": "What product helps?", "options": ["Landed-cost models under each tariff case", "Cheaper solar panels from one source", "A tool that ignores trade rules"], "correctIndex": 0, "consequences": ["Clear costs speed up pricing deals.", "One source is a concentration risk.", "Ignoring rules creates legal risk."], "explanation": "Developers price PPAs on expected costs. Modeling tariffs clarifies them."}, "proReasoning": "Founders turn policy fog into numbers developers can price.", "commonMistake": "Offering a product that only works if rules disappear.", "mentalModel": "Turn fog into numbers."}, "curiosity": {"call": {"kind": "theCall", "situation": "How does a tariff on panels reach a company buying clean power?", "prompt": "What's the path?", "options": ["Tariffs have no effect on contract prices", "Higher project costs raise contract prices", "The buyer pays the whole tariff directly"], "correctIndex": 1, "consequences": ["They showed up in 2025 prices.", "Costs pass from developer to buyer.", "Importers pay it first, then pass it on."], "explanation": "Developers pass higher costs and risk into PPA prices."}, "proReasoning": "Costs travel down the chain. A tariff at the dock becomes a price in a contract.", "commonMistake": "Thinking only importers feel a tariff.", "mentalModel": "Costs flow down the chain."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:605d0ec29cfc$ml$]::text[]),
($ml$1ee08a64-51f8-52db-80de-3afa748c63ab$ml$::uuid, $ml$cleanenergy$ml$, 14, 3, $ml${"id": "cleanenergy-d14-c3", "title": "Sign now or wait", "lessonTitle": "What a solar PPA costs", "slot": 3, "type": "decide", "brief": {"headline": "You buy clean power for a company. North American solar PPAs rose 9% in a year to $61.67 per MWh, while European prices fell to €57.44.", "kicker": "Decide: lock in a contract now, or wait for prices to ease?", "fullText": "Your company wants a 15-year solar contract in the US. Prices have risen for several quarters as tariffs, permitting delays and supplier rules raise developers' costs.\n\nIn Europe, prices kept falling as supply outran demand and negative power prices spread. A PPA price is what the buyer pays per megawatt-hour for the contract's life, and higher project risks raise it.", "sources": [{"url": "https://www.pv-tech.org/north-american-solar-ppa-prices-climb-us61-67-mwh-european-prices-continue-fall/", "label": "PV Tech, North American solar PPA prices climb to $61.67/MWh"}]}, "evidence": {"kind": "faceOff", "prompt": "Where were solar PPA prices falling in late 2025?", "left": {"name": "North America", "note": "Tariff and permit uncertainty"}, "right": {"name": "Europe", "note": "Supply ahead of demand"}, "correctIndex": 1, "explanation": "European prices fell while North American prices rose."}, "numbers": {"kind": "numberSense", "prompt": "To the nearest euro, what was the Q4 2025 European solar PPA price per MWh?", "min": 0, "max": 150, "value": 57, "unit": "€", "explanation": "About €57: €57.44 per MWh, still falling."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CFO asks whether to sign now or wait a year.", "prompt": "What do you recommend?", "options": ["Wait, since prices always fall", "Sign everything at any price", "Sign part now and keep some open"], "correctIndex": 2, "consequences": ["US prices rose for a year.", "You may overpay at the peak.", "You hedge against both rising and falling prices."], "explanation": "With policy risk rising, splitting the purchase hedges your timing."}, "proReasoning": "Energy buyers stage contracts to avoid betting on one moment.", "commonMistake": "Assuming prices must fall back soon.", "mentalModel": "Stage the buy."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a US solar developer.", "prompt": "What do rising PPA prices signal?", "options": ["Costs and risks it must pass on", "Easy profits from eager buyers", "A collapse in clean power demand"], "correctIndex": 0, "consequences": ["Watch margins, not just prices.", "Costs rose alongside prices.", "Buyers kept signing."], "explanation": "Rising US PPA prices reflect tariff and permitting risk. Watch developer margins."}, "proReasoning": "Investors watch the spread between price and cost. That is the margin that matters.", "commonMistake": "Cheering higher prices without checking costs.", "mentalModel": "Watch the spread."}, "build_startup": {"call": {"kind": "theCall", "situation": "Corporate buyers struggle to time PPA purchases.", "prompt": "What could your startup offer?", "options": ["Contracts with no fixed price", "Price indices and deal timing tools", "A new type of solar panel"], "correctIndex": 1, "consequences": ["Buyers want price certainty.", "Data helps buyers time their deals.", "Panels are not the bottleneck."], "explanation": "Corporate buyers track PPA indices to time deals. Data tools help."}, "proReasoning": "Founders sell clarity where prices swing. Buyers pay for good timing.", "commonMistake": "Selling hardware when the need is market data.", "mentalModel": "Sell timing clarity."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why are solar contracts cheaper in Europe than in the US?", "prompt": "What's one reason?", "options": ["Europe banned solar tariffs forever", "European panels are made of gold", "Europe has more supply than demand"], "correctIndex": 2, "consequences": ["No permanent ban was mentioned.", "Panels are made of silicon.", "Surplus pushes contract prices down."], "explanation": "European prices fell as supply outpaced demand and negative power prices spread."}, "proReasoning": "Supply and demand set contract prices too. Surplus means lower prices.", "commonMistake": "Assuming one global price for solar contracts.", "mentalModel": "Surplus lowers prices."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c20ae95d4a07$ml$]::text[]),
($ml$bfba4921-4ec1-5be5-8889-cee30d67e5ba$ml$::uuid, $ml$cleanenergy$ml$, 15, 1, $ml${"id": "cleanenergy-d15-c1", "title": "Amazon moves to the front of the meter", "lessonTitle": "Big Tech sets the market", "slot": 1, "type": "apply", "brief": {"headline": "In June 2025, Talen Energy signed a 17-year, $18 billion deal to supply Amazon with up to 1,920 MW from its Susquehanna nuclear plant. The power now flows over the grid, after FERC rejected a larger direct hookup.", "kicker": "Apply Big Tech buying power to a nuclear deal.", "fullText": "Amazon's data center campus first took 300 MW straight from the plant, behind the meter. In November 2024, FERC voted 2 to 1 to reject raising that to 480 MW.\n\nThe new deal runs through 2042 on a front-of-the-meter structure: Talen acts as Amazon's retail supplier, and PPL Electric delivers the power over the grid. Deliveries ramp to 1,680 to 1,920 MW by 2032.", "sources": [{"url": "https://www.powermag.com/talen-amazon-launch-18b-nuclear-ppa-a-grid-connected-ipp-model-for-the-data-center-era/", "label": "POWER, Talen and Amazon launch $18B nuclear PPA"}, {"url": "https://www.utilitydive.com/news/corporate-clean-energy-procurement-ppa-meta-amazon-google/812591/", "label": "Utility Dive, BNEF on corporate clean energy buying in 2025"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The deal is worth about $18 billion.", "FERC approved the bigger direct hookup.", "Deliveries ramp up to 1,920 MW by 2032."], "fakeIndex": 1, "explanation": "FERC rejected raising the direct hookup to 480 MW, so the deal moved to the grid."}, "numbers": {"kind": "numberSense", "prompt": "How many years does the Talen and Amazon deal run?", "min": 0, "max": 40, "value": 17, "unit": "years", "explanation": "17 years, through 2042."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks what changed in the Talen and Amazon deal.", "prompt": "What is your answer?", "options": ["The whole deal was cancelled by FERC", "It moved from a direct hookup to the grid", "Amazon bought the whole nuclear plant"], "correctIndex": 1, "consequences": ["The deal grew; only the hookup was rejected.", "Front of the meter, delivered by PPL.", "Amazon buys power, not the plant."], "explanation": "After FERC rejected the larger co-location, the deal moved to a grid-connected structure."}, "proReasoning": "Knowing the deal structure, not just the size, sets you apart in energy roles.", "commonMistake": "Treating every big tech deal as the same kind of contract.", "mentalModel": "Know the structure, not just the size."}, "invest": {"call": {"kind": "theCall", "situation": "You hold Talen shares after the $18 billion deal.", "prompt": "What is the deal's main value to Talen?", "options": ["Ownership of Amazon data centers", "A guaranteed rise in power prices", "Long-term contracted revenue"], "correctIndex": 2, "consequences": ["Talen sells power; it owns no data centers.", "The price is contracted, not rising.", "17 years of revenue from a strong buyer."], "explanation": "A long contract with a hyperscaler makes the plant's revenue predictable."}, "proReasoning": "Investors value hyperscaler contracts for their length and credit quality.", "commonMistake": "Overlooking the buyer's credit in valuing a deal.", "mentalModel": "Length and credit make value."}, "build_startup": {"call": {"kind": "theCall", "situation": "Regulators pushed big data center loads onto the grid, not behind the meter.", "prompt": "What need does that create?", "options": ["Grid delivery and planning for big loads", "More behind-the-meter hookups at plants", "Data centers that have no power needs"], "correctIndex": 0, "consequences": ["Large loads on the grid need planning.", "FERC rejected the bigger hookup.", "Data centers need lots of power."], "explanation": "With deals moving to the grid, planning and delivery for large loads matter more."}, "proReasoning": "Founders follow where regulators steer demand. Here it was onto the grid.", "commonMistake": "Building for a structure regulators just rejected.", "mentalModel": "Follow the regulator's steer."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why does Amazon want power from a nuclear plant?", "prompt": "What's the main reason?", "options": ["Amazon wants to run the reactors itself", "Data centers need steady clean power", "Nuclear power is free to buy"], "correctIndex": 1, "consequences": ["Talen runs the plant.", "Nuclear runs day and night, carbon-free.", "Amazon pays $18 billion."], "explanation": "Hyperscalers want power that runs around the clock."}, "proReasoning": "Big tech buys firm power for always-on data centers. Nuclear fits that need.", "commonMistake": "Assuming tech companies only buy solar and wind.", "mentalModel": "Always-on use wants firm supply."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:26ac6148f404$ml$]::text[]),
($ml$50f4454e-cffa-5c27-93cf-b01c2f64ec49$ml$::uuid, $ml$cleanenergy$ml$, 15, 2, $ml${"id": "cleanenergy-d15-c2", "title": "Four buyers, half the market", "lessonTitle": "Big Tech sets the market", "slot": 2, "type": "connect", "brief": {"headline": "Meta, Amazon, Google and Microsoft made up 49% of corporate clean power buying in 2025. Their long PPAs, like Microsoft's 20-year deal for Three Mile Island, now shape what gets built.", "kicker": "Connect day 13 and day 15: a few big PPA buyers set the market.", "fullText": "On day 13 you saw how a single 20-year PPA helped justify restarting an 835 MW reactor.\n\nOn day 15, BloombergNEF found the four hyperscalers made up 49% of corporate clean power buying in 2025. Meta and Amazon alone contracted 20.4 GW, including 4.7 GW of nuclear. In the US, the number of different corporate buyers fell 51% to just 33.", "sources": [{"url": "https://www.utilitydive.com/news/corporate-clean-energy-procurement-ppa-meta-amazon-google/812591/", "label": "Utility Dive, BNEF on corporate clean energy buying in 2025"}, {"url": "https://www.orrick.com/en/News/2024/10/Microsoft-Signs-20-Year-PPA-with-Constellation", "label": "Orrick, Microsoft signs 20-year PPA with Constellation"}]}, "evidence": {"kind": "sortSignal", "prompt": "Is it a sign of concentration among buyers?", "buckets": ["Concentration", "Not concentration"], "items": [{"text": "Four firms make 49% of corporate buying", "bucket": 0}, {"text": "US unique buyers fall 51% to 33", "bucket": 0}, {"text": "Many small firms each sign deals", "bucket": 1}, {"text": "Buying spread evenly across sectors", "bucket": 1}], "explanation": "A few hyperscalers dominate, and the number of distinct US buyers halved."}, "numbers": {"kind": "numberSense", "prompt": "What share of corporate clean power buying came from the four hyperscalers in 2025?", "min": 0, "max": 80, "value": 49, "unit": "%", "tolerance": 0.06, "explanation": "49%: Meta, Amazon, Google and Microsoft."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You want to work on PPAs. Where are the biggest buyer teams?", "prompt": "Which employers do you target?", "options": ["Small firms that buy power yearly", "Retail shops with rooftop solar", "The hyperscalers that sign gigawatts"], "correctIndex": 2, "consequences": ["Smaller buyers left the market.", "Rooftop solar is not PPA work.", "They run large energy teams."], "explanation": "Hyperscalers run large energy teams that sign gigawatts of deals."}, "proReasoning": "Job seekers follow the volume. Half the buying sits in four companies.", "commonMistake": "Spreading applications without knowing where deals happen.", "mentalModel": "Follow the buying volume."}, "invest": {"call": {"kind": "theCall", "situation": "A developer relies on one hyperscaler for most of its contracts.", "prompt": "What risk do you flag?", "options": ["Too much depends on one buyer's plans", "Hyperscalers never pay their bills", "Contracts with big firms are short"], "correctIndex": 0, "consequences": ["A shift in one buyer's strategy hits hard.", "They are strong payers.", "Many run 15 to 20 years."], "explanation": "Half of corporate demand comes from four firms. Their strategy moves the whole market."}, "proReasoning": "Investors watch customer concentration. When four buyers are half the market, their choices matter.", "commonMistake": "Treating a strong buyer as zero risk.", "mentalModel": "Concentration cuts both ways."}, "build_startup": {"call": {"kind": "theCall", "situation": "Most clean power demand now comes from four companies.", "prompt": "How do you shape your product?", "options": ["Around one-year power deals", "Around what hyperscalers need most", "Around small buyers who left"], "correctIndex": 1, "consequences": ["Buyers want long-term supply.", "That is where the demand is.", "They stepped back in 2025."], "explanation": "With four buyers making half the market, their needs shape what sells."}, "proReasoning": "Founders design for the buyers who hold the budget. In 2025, that was four firms.", "commonMistake": "Designing for a buyer group that is shrinking.", "mentalModel": "Design for who holds the budget."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why do a few tech firms matter so much for clean energy?", "prompt": "What's the answer?", "options": ["They own every power plant", "They set electricity prices by law", "They buy half the corporate clean power"], "correctIndex": 2, "consequences": ["They buy power; others own plants.", "Prices are set by markets.", "49% of corporate buying in 2025."], "explanation": "Meta, Amazon, Google and Microsoft made up 49% of corporate clean power buying in 2025."}, "proReasoning": "Buyers with that much share decide which projects get built.", "commonMistake": "Thinking clean energy demand is spread evenly.", "mentalModel": "Big buyers steer the build."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:670caa1613d6$ml$]::text[]),
($ml$dc9c6c43-5130-520c-9698-aa7249ba1817$ml$::uuid, $ml$cleanenergy$ml$, 15, 3, $ml${"id": "cleanenergy-d15-c3", "title": "What to offer a hyperscaler", "lessonTitle": "Big Tech sets the market", "slot": 3, "type": "decide", "brief": {"headline": "You develop clean power, and most buyers are now hyperscalers. Big Tech is turning to nuclear, hydro and geothermal for power that runs around the clock.", "kicker": "Decide: what do you put in front of Big Tech?", "fullText": "Meta, Amazon, Google and Microsoft made up 49% of corporate clean power buying in 2025. Meta and Amazon contracted 20.4 GW, including 4.7 GW of nuclear.\n\nRising project costs and policy uncertainty pushed smaller buyers out: unique US corporate buyers fell 51% to 33. The remaining giants want steady supply for data centers that never sleep. In corporate clean energy, a handful of tech giants now set what gets built.", "sources": [{"url": "https://www.utilitydive.com/news/corporate-clean-energy-procurement-ppa-meta-amazon-google/812591/", "label": "Utility Dive, BNEF on corporate clean energy buying in 2025"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What are hyperscalers increasingly turning to?", "options": ["Nuclear, hydro and geothermal", "Only cheap midday solar", "Short one-year contracts"], "correctIndex": 0, "explanation": "They want power that runs around the clock, not only daytime solar."}, "numbers": {"kind": "numberSense", "prompt": "How many unique US corporate clean power buyers were left in 2025?", "min": 0, "max": 100, "value": 33, "explanation": "33, down 51% as costs and policy risks rose."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO asks what product to lead with for hyperscalers.", "prompt": "What do you recommend?", "options": ["Firm clean power around the clock", "Only cheap midday solar power", "Short one-year contracts"], "correctIndex": 0, "consequences": ["That matches what Big Tech buys.", "They want more than daytime power.", "They seek long-term supply."], "explanation": "Big Tech is pivoting to nuclear, hydro and geothermal for steady supply."}, "proReasoning": "Developers lead with what the buyer is shifting toward. In 2025, that was firm power.", "commonMistake": "Pitching last decade's product to this decade's buyer.", "mentalModel": "Pitch the buyer's next need."}, "invest": {"call": {"kind": "theCall", "situation": "You can back a solar-only developer or a geothermal developer.", "prompt": "Which fits hyperscaler demand better?", "options": ["Neither, since tech stopped buying", "Geothermal, which runs around the clock", "Solar-only, since it is cheapest"], "correctIndex": 1, "consequences": ["They bought 49% of corporate deals.", "Firm supply matches always-on data centers.", "Cheap daytime power is not what they seek now."], "explanation": "Big Tech wants steady clean power. Technologies that deliver it have eager buyers."}, "proReasoning": "Investors follow what the biggest buyers want next. Firm power had the momentum.", "commonMistake": "Backing the cheapest option when buyers want reliability.", "mentalModel": "Back what buyers want next."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup pairs solar with long-duration storage.", "prompt": "How do you pitch a hyperscaler?", "options": ["As the cheapest midday power around", "As a one-year trial contract to start", "As firm clean power through the night"], "correctIndex": 2, "consequences": ["Midday is not their gap.", "They want long-term supply.", "That speaks to their round-the-clock need."], "explanation": "Big Tech wants steady clean power. Frame storage as firm supply."}, "proReasoning": "Founders frame products in the buyer's terms. \"Firm\" beats \"cheap\" for hyperscalers.", "commonMistake": "Leading with price when the buyer leads with reliability.", "mentalModel": "Speak the buyer's language."}, "curiosity": {"call": {"kind": "theCall", "situation": "Why would tech giants buy geothermal power?", "prompt": "What's the reason?", "options": ["It runs day and night, carbon-free", "It is the only legal power source", "It is free to produce"], "correctIndex": 0, "consequences": ["Steady output fits always-on data centers.", "Many sources are legal.", "It costs money to build and run."], "explanation": "Data centers run around the clock, so steady clean sources appeal to them."}, "proReasoning": "Match the source to the use. Always-on data centers want always-on power.", "commonMistake": "Assuming tech picks power sources for image alone.", "mentalModel": "Always-on wants always-on."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:142c2188c4a6$ml$]::text[])
